var RATES = { MXN:1 };
CURRENCY_LIST.forEach(function(c){ if(!(c.code in RATES)) RATES[c.code] = 1; }); // placeholder hasta que llegue la API
RATES.USD = (1/USD_MXN);
var CUR_SYM = {}; CURRENCY_LIST.forEach(function(c){ CUR_SYM[c.code] = c.sym; });
var CUR_SUF = {}; CURRENCY_LIST.forEach(function(c){ CUR_SUF[c.code] = ' ' + c.code; });

/* ── TIPO DE CAMBIO EN TIEMPO REAL ──
   Consulta las tasas reales del dolar/monedas desde una API gratuita.
   La base de todo es MXN (1). Las tasas se guardan como: 1 MXN = X moneda. */
function actualizarTiposDeCambio(){
  // API gratuita sin key. Base MXN.
  fetch('https://open.er-api.com/v6/latest/MXN')
    .then(function(r){ return r.json(); })
    .then(function(d){
      if(!d || !d.rates) return;
      var r = d.rates;
      // Actualizar TODAS las monedas del catalogo que la API traiga
      CURRENCY_LIST.forEach(function(c){
        if(c.code !== 'MXN' && r[c.code]) RATES[c.code] = r[c.code];
      });
      // USD_MXN = cuantos MXN es 1 USD (para conversiones internas de USDT)
      if(r.USD) USD_MXN = 1 / r.USD;
      if(typeof recalcularPreciosDiamantes === 'function') recalcularPreciosDiamantes();
      // Guardar en cache local con fecha
      try {
        localStorage.setItem('cs_rates', JSON.stringify({ rates: RATES, usd_mxn: USD_MXN, ts: Date.now() }));
      } catch(e){}
      // Refrescar la UI si hay precios mostrandose
      if(typeof renderDiamCatalogo === 'function') try { renderDiamCatalogo(); } catch(e){}
      if(typeof renderLikes2k === 'function') try { renderLikes2k(); } catch(e){}
      if(typeof renderHonorPrecios === 'function') try { renderHonorPrecios(); } catch(e){}
      if(typeof _pintarSelectorMoneda === 'function') try { _pintarSelectorMoneda(); } catch(e){}
      console.log('[TC] Tipos de cambio actualizados. 1 USD =', USD_MXN.toFixed(2), 'MXN');
    })
    .catch(function(e){ console.warn('[TC] No se pudo actualizar el tipo de cambio, usando el ultimo conocido', e); });
}

// Cargar el ultimo TC guardado (para no arrancar con el fijo) y luego actualizar
(function _cargarTCGuardado(){
  try {
    var cache = JSON.parse(localStorage.getItem('cs_rates') || 'null');
    if(cache && cache.rates){
      // Usar cache solo si tiene menos de 12 horas
      if(Date.now() - (cache.ts||0) < 12*3600*1000){
        RATES = cache.rates;
        if(cache.usd_mxn) USD_MXN = cache.usd_mxn;
      }
    }
  } catch(e){}
})();

// Actualizar al cargar y cada 6 horas
if(typeof window !== 'undefined'){
  setTimeout(actualizarTiposDeCambio, 1500);
  setInterval(actualizarTiposDeCambio, 6*3600*1000);
}

// Calcula el inicio real del periodo (dia = hoy 00:00, semana = lunes 00:00, mes = dia 1)
function _inicioPeriodo(period){
  var ahora = new Date();
  if(period === 'dia'){
    var d = new Date(ahora); d.setHours(0,0,0,0);
    return d.toISOString();
  }
  if(period === 'semana'){
    var s = new Date(ahora);
    s.setHours(0,0,0,0);
    // getDay(): 0=domingo, 1=lunes ... queremos que la semana empiece el LUNES
    var dia = s.getDay();
    var diffAlLunes = (dia === 0) ? 6 : (dia - 1); // domingo cuenta como fin de semana anterior
    s.setDate(s.getDate() - diffAlLunes);
    return s.toISOString();
  }
  if(period === 'mes'){
    var m = new Date(ahora.getFullYear(), ahora.getMonth(), 1, 0, 0, 0, 0);
    return m.toISOString();
  }
  return null; // historico = sin filtro
}


function fmt(mxn){
  if(!mxn&&mxn!==0) return '';
  var cur=CURRENCY;
  if(cur!=='MXN' && (RATES[cur]||1)===1) cur='MXN'; // la tasa aun no llego: se muestra en pesos antes que un monto equivocado
  var rate=RATES[cur]||1, sym=CUR_SYM[cur]||'$', suf=CUR_SUF[cur]||'';
  var val=mxn*rate, str;
  // Si el monto en MXN tiene decimales (ej: 12.50), mostrarlos
  var tieneDecimal = (Math.round(mxn*100) % 100) !== 0;
  if(cur==='MXN') str=sym+(tieneDecimal ? val.toLocaleString('es-MX',{minimumFractionDigits:2,maximumFractionDigits:2}) : Math.round(val).toLocaleString('es-MX'));
  else if(cur==='ARS') str=sym+Math.round(val).toLocaleString('es-AR');
  else str=sym+(Math.abs(val)>=1000 ? Math.round(val).toLocaleString('es-MX') : val.toFixed(2));
  return str+suf;
}

// ═══ Selector de moneda ampliado (dropdown en el navbar) ═══
function toggleCurrencyDropdown(){
  var dd = document.getElementById('cur-dropdown');
  var wrap = document.querySelector('.topbar-center');
  if(!dd) return;
  var willOpen = !dd.classList.contains('open');
  dd.classList.toggle('open');
  if(wrap) wrap.classList.toggle('open', willOpen);
  if(willOpen) _pintarListaMonedas();
}
function closeCurrencyDropdown(){
  var dd = document.getElementById('cur-dropdown');
  var wrap = document.querySelector('.topbar-center');
  if(dd) dd.classList.remove('open');
  if(wrap) wrap.classList.remove('open');
}
function _pintarListaMonedas(){
  var list = document.getElementById('cur-dropdown-list');
  if(!list) return;
  list.innerHTML = CURRENCY_LIST.map(function(c){
    var activo = (c.code === CURRENCY);
    return '<div class="cur-opt'+(activo?' active':'')+'" onclick="selectCurrency(\''+c.code+'\')">'
      + '<span class="cur-opt-flag">'+c.flag+'</span>'
      + '<span class="cur-opt-name">'+c.name+'</span>'
      + '<span class="cur-opt-code">'+c.code+'</span>'
      + (activo ? '<span class="cur-opt-check">&#10003;</span>' : '')
      + '</div>';
  }).join('');
}
function selectCurrency(code){
  changeCurrency(code);
  _pintarSelectorMoneda();
  closeCurrencyDropdown();
}
function _pintarSelectorMoneda(){
  var c = CURRENCY_LIST.find(function(x){ return x.code === CURRENCY; }) || CURRENCY_LIST[0];
  var flagEl = document.getElementById('cur-btn-flag');
  var codeEl = document.getElementById('cur-btn-code');
  if(flagEl) flagEl.textContent = c.flag;
  if(codeEl) codeEl.textContent = c.code;
}
// Cerrar el dropdown si se toca fuera de el
document.addEventListener('click', function(e){
  var dd = document.getElementById('cur-dropdown');
  var btn = document.getElementById('cur-btn');
  var wrap = document.querySelector('.topbar-center');
  if(dd && dd.classList.contains('open') && !dd.contains(e.target) && (!btn || !btn.contains(e.target))){
    dd.classList.remove('open');
    if(wrap) wrap.classList.remove('open');
  }
});

