/* ================================================================
   CENTRO DE SOPORTE — tickets, chat, respuestas automaticas
================================================================ */
var _sopTicketActual = null;   // ticket abierto actualmente en el chat
var _sopArchivoB64 = null;     // adjunto pendiente de enviar
var _sopEnviando = false;

var SOP_CATEGORIA_LABEL = { pedido:'Mi pedido', pago:'Pagos y comprobantes', entrega:'Entrega / demora', cuenta:'Mi cuenta', otro:'Otra cosa' };
var SOP_ESTADO_LABEL = { pendiente:'Pendiente', en_atencion:'En atencion', resuelto:'Resuelto', cerrado:'Cerrado' };

// ── Navegacion entre las 3 vistas de la pagina de soporte ──────
/* ================================================================
   PÁGINA FREE FIRE — navegación Tienda / Cuentas
================================================================ */
function ffVolverInicio(){
  document.getElementById('ff-vista-inicio').style.display = 'block';
  document.getElementById('ff-vista-tienda').style.display = 'none';
  document.getElementById('ff-vista-cuentas').style.display = 'none';
}
function ffIrTienda(){
  document.getElementById('ff-vista-inicio').style.display = 'none';
  document.getElementById('ff-vista-tienda').style.display = 'block';
  document.getElementById('ff-vista-cuentas').style.display = 'none';
}
function ffIrCuentas(){
  document.getElementById('ff-vista-inicio').style.display = 'none';
  document.getElementById('ff-vista-tienda').style.display = 'none';
  document.getElementById('ff-vista-cuentas').style.display = 'block';
}

function sopVolverLista(){
  document.getElementById('sop-vista-lista').style.display = 'block';
  document.getElementById('sop-vista-nuevo').style.display = 'none';
  document.getElementById('sop-vista-chat').style.display = 'none';
  _sopTicketActual = null;
  sopCargarLista();
}
function sopAbrirNuevo(){
  if(!authSession){ showToast('Inicia sesion para usar el soporte'); setTimeout(showAuthModal, 600); return; }
  document.getElementById('sop-vista-lista').style.display = 'none';
  document.getElementById('sop-vista-nuevo').style.display = 'block';
  document.getElementById('sop-vista-chat').style.display = 'none';
}

// ── Lista de tickets del usuario ────────────────────────────────
function sopCargarLista(){
  var cont = document.getElementById('sop-lista-tickets');
  if(!cont) return;
  if(!authSession){
    cont.innerHTML = '<div class="sop-empty"><div class="sop-empty-ico"><svg width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg></div><div class="sop-empty-title">Inicia sesion para ver tu soporte</div></div>';
    return;
  }
  cont.innerHTML = '<div style="text-align:center;padding:1.5rem;color:var(--muted);font-size:.82rem">Cargando...</div>';

  sb.get('tickets', 'user_id=eq.'+authSession.id+'&order=updated_at.desc&limit=30').then(function(rows){
    if(!rows || !rows.length){
      cont.innerHTML = '<div class="sop-empty">'
        + '<div class="sop-empty-ico"><svg width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg></div>'
        + '<div class="sop-empty-title">Aun no tienes conversaciones</div>'
        + '<div class="sop-empty-sub">Cuando contactes con nuestro equipo, tus conversaciones apareceran aqui.</div>'
        + '<button class="sop-empty-btn" onclick="sopAbrirNuevo()">Iniciar una conversacion</button>'
        + '</div>';
      return;
    }

    // Traer el ultimo mensaje de cada ticket para mostrarlo en la tarjeta
    var ids = rows.map(function(t){ return t.id; }).join(',');
    sb.get('ticket_messages', 'ticket_id=in.('+ids+')&order=created_at.desc').then(function(msgs){
      var ultimoPorTicket = {};
      (msgs||[]).forEach(function(m){ if(!ultimoPorTicket[m.ticket_id]) ultimoPorTicket[m.ticket_id] = m; });

      cont.innerHTML = rows.map(function(t){
        var badge = 'sop-badge--'+t.status;
        var unread = t.unread_user ? ' unread' : '';
        var um = ultimoPorTicket[t.id];
        var ultimoTxt = um ? (um.sender_type === 'user' ? 'Tu: ' : '') + (um.message || (um.attachment_url ? 'Imagen adjunta' : '')) : (SOP_CATEGORIA_LABEL[t.category]||t.category);
        var fecha = t.updated_at ? _tiempoRelativo(t.updated_at) : '';
        return '<div class="sop-ticket-card'+unread+'" onclick="sopAbrirTicket('+t.id+')">'
          + '<div class="sop-ticket-av"><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M3 11a9 9 0 0 1 18 0v5a3 3 0 0 1-3 3h-1v-7h4M3 11v5a3 3 0 0 0 3 3h1v-7H3"/></svg></div>'
          + '<div class="sop-ticket-body">'
          +   '<div class="sop-ticket-top"><span style="font-weight:700;color:#fff;font-size:.85rem">'+_esc(t.subject)+'</span><span class="sop-badge '+badge+'">'+(SOP_ESTADO_LABEL[t.status]||t.status)+'</span></div>'
          +   '<div class="sop-ticket-last">'+_esc(ultimoTxt)+'</div>'
          +   '<div class="sop-ticket-meta">'+t.codigo+' &middot; '+fecha+'</div>'
          + '</div>'
          + (t.unread_user ? '<span class="sop-unread-dot"></span>' : '')
          + '</div>';
      }).join('');
    }).catch(function(){
      // Si falla traer los ultimos mensajes, mostrar igual la lista sin ese detalle
      cont.innerHTML = rows.map(function(t){
        var badge = 'sop-badge--'+t.status;
        var unread = t.unread_user ? ' unread' : '';
        return '<div class="sop-ticket-card'+unread+'" onclick="sopAbrirTicket('+t.id+')">'
          + '<div class="sop-ticket-av"><svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M3 11a9 9 0 0 1 18 0v5a3 3 0 0 1-3 3h-1v-7h4M3 11v5a3 3 0 0 0 3 3h1v-7H3"/></svg></div>'
          + '<div class="sop-ticket-body">'
          +   '<div class="sop-ticket-top"><span style="font-weight:700;color:#fff;font-size:.85rem">'+_esc(t.subject)+'</span><span class="sop-badge '+badge+'">'+(SOP_ESTADO_LABEL[t.status]||t.status)+'</span></div>'
          +   '<div class="sop-ticket-meta">'+t.codigo+' &middot; '+(SOP_CATEGORIA_LABEL[t.category]||t.category)+'</div>'
          + '</div></div>';
      }).join('');
    });
  }).catch(function(){ cont.innerHTML = '<div style="text-align:center;padding:1.5rem;color:var(--muted)">Error al cargar tus conversaciones.</div>'; });
}

// ── Crear un ticket nuevo ───────────────────────────────────────
function sopCrearTicket(categoria, asunto){
  if(!authSession){ showToast('Inicia sesion'); return; }
  sb.post('tickets', {
    user_id: authSession.id,
    username: authSession.username,
    subject: asunto,
    category: categoria,
    status: 'pendiente',
    priority: 'normal'
  }).then(function(rows){
    var t = rows && rows[0];
    if(!t){ showToast('No se pudo crear la conversacion'); return; }
    // Mensaje de bienvenida automatico del bot
    var bienvenida = _sopMensajeBienvenida(categoria);
    sb.post('ticket_messages', { ticket_id: t.id, sender_type:'bot', sender_name:'CiberStore IA', message: bienvenida }).then(function(){
      sopAbrirTicket(t.id);
      if(typeof tgSend === 'function'){
        tgSend('\uD83C\uDFA7 SOPORTE - Nuevo ticket\n\uD83C\uDFAB '+t.codigo+'\n\uD83D\uDC64 '+authSession.username+'\n\uD83D\uDCC2 '+(SOP_CATEGORIA_LABEL[categoria]||categoria)+'\n\uD83D\uDCDD '+asunto);
      }
    });
  }).catch(function(e){ showToast('Error al crear ticket'); console.error('[SOPORTE]', e); });
}

function _sopMensajeBienvenida(categoria){
  var textos = {
    pedido: 'Hola! Cuentame que pasa con tu pedido y te ayudo. Si tienes el numero de pedido, compartelo para revisarlo mas rapido.',
    pago: 'Hola! Cuentame el problema con tu pago o comprobante. Si ya lo enviaste, dime el monto y el metodo que usaste.',
    entrega: 'Hola! Cuentame que producto esperas y cuanto tiempo ha pasado, y reviso el estado contigo.',
    cuenta: 'Hola! Cuentame que necesitas sobre tu cuenta.',
    otro: 'Hola! Cuentame en que te puedo ayudar.'
  };
  return textos[categoria] || textos.otro;
}

// ── Abrir un ticket y mostrar su chat ───────────────────────────
function sopAbrirTicket(ticketId){
  _sopTicketActual = ticketId;
  document.getElementById('sop-vista-lista').style.display = 'none';
  document.getElementById('sop-vista-nuevo').style.display = 'none';
  document.getElementById('sop-vista-chat').style.display = 'block';

  sb.get('tickets', 'id=eq.'+ticketId+'&limit=1').then(function(rows){
    var t = rows && rows[0];
    if(!t){ showToast('Ticket no encontrado'); sopVolverLista(); return; }

    document.getElementById('sop-chat-codigo').textContent = t.codigo;
    document.getElementById('sop-chat-estado').textContent = SOP_CATEGORIA_LABEL[t.category] || t.category;
    var badgeEl = document.getElementById('sop-chat-status-badge');
    badgeEl.textContent = SOP_ESTADO_LABEL[t.status] || t.status;
    badgeEl.className = 'sop-badge sop-badge--' + t.status;

    var btnEscalar = document.getElementById('sop-btn-escalar');
    var inputRow = document.getElementById('sop-input-row');
    if(t.status === 'cerrado'){
      if(btnEscalar) btnEscalar.style.display = 'none';
      if(inputRow) inputRow.style.display = 'none';
    } else {
      if(inputRow) inputRow.style.display = 'flex';
      if(btnEscalar) btnEscalar.style.display = t.needs_human ? 'none' : 'flex';
    }

    // Pedido relacionado (si el ticket lo tiene)
    var pedidoBox = document.getElementById('sop-pedido-rel');
    if(t.pedido_id){
      sb.get('pedidos', 'id=eq.'+t.pedido_id+'&limit=1').then(function(peds){
        var p = peds && peds[0];
        if(p && pedidoBox){
          pedidoBox.style.display = 'block';
          pedidoBox.innerHTML = '<b style="color:#1b87f5">Pedido relacionado</b><br/>'+_esc(p.producto)+' &middot; '+(ESTADO_LABEL[p.estado]?ESTADO_LABEL[p.estado].t:p.estado);
        }
      });
    } else if(pedidoBox){ pedidoBox.style.display = 'none'; }

    // Marcar como leido por el usuario
    if(t.unread_user) sb.patch('tickets', { unread_user:false }, 'id=eq.'+ticketId);

    sopCargarMensajes(ticketId);
  }).catch(function(){ showToast('Error al abrir el ticket'); });
}

function sopCargarMensajes(ticketId){
  var feed = document.getElementById('sop-chat-feed');
  feed.innerHTML = '<div style="text-align:center;padding:1rem;color:var(--muted);font-size:.78rem">Cargando...</div>';
  sb.get('ticket_messages', 'ticket_id=eq.'+ticketId+'&order=created_at.asc').then(function(rows){
    if(!rows || !rows.length){ feed.innerHTML = ''; return; }
    feed.innerHTML = rows.map(_sopMsgHTML).join('');
    feed.scrollTop = feed.scrollHeight;
  }).catch(function(){ feed.innerHTML = '<div style="text-align:center;padding:1rem;color:var(--muted)">Error al cargar mensajes.</div>'; });
}

function _sopMsgHTML(m){
  var esMio = m.sender_type === 'user';
  var fecha = m.created_at ? new Date(m.created_at).toLocaleString('es-MX', {day:'2-digit', month:'short', hour:'2-digit', minute:'2-digit'}) : '';
  var claseGlobo = esMio ? 'sop-msg me' : (m.sender_type === 'bot' ? 'sop-msg bot' : 'sop-msg agent');
  var label = '';
  if(m.sender_type === 'bot') label = '<div class="sop-msg-label bot">\uD83E\uDD16 CiberStore IA</div>';
  else if(m.sender_type === 'agent') label = '<div class="sop-msg-label agent">\uD83D\uDC64 '+_esc(m.sender_name)+' &middot; Agente</div>';
  var img = m.attachment_url ? '<img src="'+m.attachment_url+'" alt="adjunto"/>' : '';
  return '<div class="sop-msg-row '+(esMio?'me':'them')+'">'
    + '<div class="'+claseGlobo+'">'+label+(m.message?_esc(m.message).replace(/\n/g,'<br/>'):'')+img+'</div>'
    + '<div class="sop-msg-time">'+fecha+'</div>'
    + '</div>';
}

// ── Adjuntar imagen ──────────────────────────────────────────────
function sopArchivoElegido(input){
  var file = input.files && input.files[0];
  if(!file) return;
  if(file.size > 5*1024*1024){ showToast('La imagen debe pesar menos de 5MB'); input.value=''; return; }
  var reader = new FileReader();
  reader.onload = function(e){
    _sopArchivoB64 = e.target.result;
    var prev = document.getElementById('sop-preview-adjunto');
    prev.style.display = 'block';
    prev.innerHTML = '<div style="display:flex;align-items:center;gap:.6rem;background:rgba(27,135,245,.06);border:1px solid rgba(27,135,245,.2);border-radius:10px;padding:.5rem .7rem">'
      + '<img src="'+_sopArchivoB64+'" style="width:36px;height:36px;border-radius:8px;object-fit:cover"/>'
      + '<span style="flex:1;font-size:.72rem;color:#c8d0e0">Imagen lista para enviar</span>'
      + '<button onclick="sopQuitarAdjunto()" style="background:none;border:none;color:#ff6b6b;cursor:pointer;font-size:.8rem">Quitar</button>'
      + '</div>';
  };
  reader.readAsDataURL(file);
}
function sopQuitarAdjunto(){
  _sopArchivoB64 = null;
  document.getElementById('sop-file-input').value = '';
  document.getElementById('sop-preview-adjunto').style.display = 'none';
}

// ── Enviar mensaje del usuario ───────────────────────────────────
// Indicador visual "escribiendo..." mientras el bot prepara su respuesta
function _sopMostrarEscribiendo(){
  var feed = document.getElementById('sop-chat-feed');
  if(!feed) return;
  var el = document.createElement('div');
  el.className = 'sop-msg-row them';
  el.id = 'sop-typing-indicator';
  el.innerHTML = '<div class="sop-msg bot"><div class="sop-typing"><span></span><span></span><span></span></div></div>';
  feed.appendChild(el);
  feed.scrollTop = feed.scrollHeight;
}

function sopEnviarMensaje(){
  if(_sopEnviando || !_sopTicketActual) return;
  var input = document.getElementById('sop-msg-input');
  var texto = (input.value || '').trim();
  if(!texto && !_sopArchivoB64){ showToast('Escribe un mensaje o adjunta una imagen'); return; }
  if(texto.length > 1000){ showToast('Mensaje muy largo (max 1000 caracteres)'); return; }

  _sopEnviando = true;
  var adjunto = _sopArchivoB64;
  var ticketId = _sopTicketActual;

  sb.post('ticket_messages', {
    ticket_id: ticketId, sender_type:'user', sender_name: authSession.username,
    message: texto, attachment_url: adjunto || null
  }).then(function(){
    input.value = '';
    sopQuitarAdjunto();
    sb.patch('tickets', { unread_admin:true, status:'pendiente' }, 'id=eq.'+ticketId);
    sopCargarMensajes(ticketId);
    _sopEnviando = false;

    // Intentar responder con el motor de reglas si el ticket aun no fue escalado a humano
    sb.get('tickets', 'id=eq.'+ticketId+'&limit=1').then(function(rows){
      var t = rows && rows[0];
      if(t && !t.needs_human && t.status !== 'resuelto' && t.status !== 'cerrado'){
        _sopMostrarEscribiendo();
        setTimeout(function(){ sopResponderAutomatico(ticketId, texto); }, 1100);
      }
    });
  }).catch(function(){ showToast('No se pudo enviar tu mensaje'); _sopEnviando = false; });
}

// ── Motor de respuestas automaticas (reglas por palabras clave) ──
// Busca en support_faq una coincidencia de palabras clave con el
// mensaje del usuario. Si encuentra una respuesta con confianza
// razonable, la envia como el bot. Si no encuentra nada, dice con
// honestidad que no tiene la respuesta y ofrece pasar con una
// persona - nunca inventa informacion.
function sopResponderAutomatico(ticketId, mensajeUsuario){
  var texto = (mensajeUsuario || '').toLowerCase();
  sb.get('support_faq', 'active=eq.true').then(function(faqs){
    var mejor = null, mejorScore = 0;
    (faqs || []).forEach(function(f){
      var palabras = (f.keywords || '').split(',').map(function(k){ return k.trim().toLowerCase(); }).filter(Boolean);
      var score = 0;
      palabras.forEach(function(p){ if(p && texto.indexOf(p) !== -1) score++; });
      if(score > mejorScore){ mejorScore = score; mejor = f; }
    });

    if(mejor && mejorScore > 0){
      sb.post('ticket_messages', { ticket_id: ticketId, sender_type:'bot', sender_name:'CiberStore IA', message: mejor.answer })
        .then(function(){ sopCargarMensajes(ticketId); });
    } else {
      var msg = 'No tengo informacion suficiente para responder eso con seguridad. Si quieres, puedo pasar tu caso con un miembro del equipo — toca "Hablar con una persona" abajo.';
      sb.post('ticket_messages', { ticket_id: ticketId, sender_type:'bot', sender_name:'CiberStore IA', message: msg })
        .then(function(){ sopCargarMensajes(ticketId); });
    }
  }).catch(function(){ /* si falla la consulta, simplemente no se autoresponde */ });
}

// ── Escalar a humano ─────────────────────────────────────────────
function sopEscalarHumano(){
  if(!_sopTicketActual) return;
  var ticketId = _sopTicketActual;
  sb.patch('tickets', { needs_human:true, status:'pendiente', priority:'alta', unread_admin:true }, 'id=eq.'+ticketId).then(function(){
    return sb.post('ticket_messages', { ticket_id: ticketId, sender_type:'bot', sender_name:'CiberStore IA', message: 'Voy a pasar tu caso con un miembro del equipo para que puedan revisarlo. En cuanto respondan lo veras aqui mismo.' });
  }).then(function(){
    showToast('Tu caso fue enviado al equipo', 2500);
    if(typeof tgSend === 'function'){
      tgSend('\uD83C\uDFA7 SOPORTE - Se solicito atencion humana\n\uD83D\uDC64 Usuario: '+authSession.username+'\n\uD83C\uDFAB Ticket ID: '+ticketId+'\n\nRevisa el panel admin > Soporte');
    }
    sopAbrirTicket(ticketId);
  }).catch(function(){ showToast('No se pudo escalar el ticket'); });
}

/* ================================================================
   PANEL ADMIN — SOPORTE
================================================================ */
var _admSopTicketActual = null;

function admSopVolver(){
  document.getElementById('adm-sop-vista-lista').style.display = 'block';
  document.getElementById('adm-sop-vista-detalle').style.display = 'none';
  _admSopTicketActual = null;
  admSopCargarLista();
}

function admSopCargarLista(){
  var body = document.getElementById('adm-sop-lista-body');
  if(!body) return;
  body.innerHTML = '<tr><td colspan="8" style="text-align:center;color:var(--muted);padding:1.5rem">Cargando...</td></tr>';

  var estado = ((document.getElementById('adm-sop-filtro-estado')||{}).value||'');
  var userF = ((document.getElementById('adm-sop-filtro-user')||{}).value||'').trim().toLowerCase();
  var codF = ((document.getElementById('adm-sop-filtro-codigo')||{}).value||'').trim().toUpperCase();

  var qs = 'order=updated_at.desc&limit=100';
  var filtros = [];
  if(estado) filtros.push('status=eq.'+estado);
  if(userF) filtros.push('username=ilike.*'+encodeURIComponent(userF)+'*');
  if(codF) filtros.push('codigo=ilike.*'+encodeURIComponent(codF)+'*');
  if(filtros.length) qs = filtros.join('&') + '&' + qs;

  sb.get('tickets', qs).then(function(rows){
    // Actualizar badge de pendientes sin responder en el nav
    var pendientes = (rows||[]).filter(function(t){ return t.unread_admin; }).length;
    var badge = document.getElementById('adm-soporte-badge');
    if(badge){
      if(pendientes > 0){ badge.style.display='inline-block'; badge.textContent = pendientes; }
      else badge.style.display = 'none';
    }

    if(!rows || !rows.length){
      body.innerHTML = '<tr><td colspan="8" style="text-align:center;color:var(--muted);padding:1.5rem">Sin tickets con esos filtros</td></tr>';
      return;
    }
    body.innerHTML = rows.map(function(t){
      var fecha = t.updated_at ? new Date(t.updated_at).toLocaleString('es-MX',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}) : '-';
      var unreadDot = t.unread_admin ? '<span style="display:inline-block;width:7px;height:7px;border-radius:50%;background:#ff6b6b;margin-right:.4rem"></span>' : '';
      return '<tr style="cursor:pointer" onclick="admSopAbrirTicket('+t.id+')">'
        + '<td>'+unreadDot+t.codigo+'</td>'
        + '<td>'+_esc(t.username)+'</td>'
        + '<td>'+_esc(t.subject)+'</td>'
        + '<td>'+(SOP_CATEGORIA_LABEL[t.category]||t.category)+'</td>'
        + '<td><span class="sop-badge sop-badge--'+t.status+'">'+(SOP_ESTADO_LABEL[t.status]||t.status)+'</span></td>'
        + '<td>'+t.priority+(t.needs_human?' \uD83D\uDEA8':'')+'</td>'
        + '<td>'+fecha+'</td>'
        + '<td><button onclick="event.stopPropagation();admSopAbrirTicket('+t.id+')" class="adm-action-btn" style="border-color:rgba(27,135,245,.3);color:#1b87f5">Abrir</button></td>'
        + '</tr>';
    }).join('');
  }).catch(function(){ body.innerHTML = '<tr><td colspan="8" style="text-align:center;color:var(--muted);padding:1.5rem">Error al cargar</td></tr>'; });
}

function admSopAbrirTicket(ticketId){
  _admSopTicketActual = ticketId;
  document.getElementById('adm-sop-vista-lista').style.display = 'none';
  document.getElementById('adm-sop-vista-detalle').style.display = 'block';

  sb.get('tickets', 'id=eq.'+ticketId+'&limit=1').then(function(rows){
    var t = rows && rows[0];
    if(!t){ showToast('Ticket no encontrado'); admSopVolver(); return; }

    document.getElementById('adm-sop-d-codigo').textContent = t.codigo;
    document.getElementById('adm-sop-d-user').textContent = t.username + ' \u00b7 ' + (SOP_CATEGORIA_LABEL[t.category]||t.category);
    document.getElementById('adm-sop-d-estado').value = t.status;
    document.getElementById('adm-sop-d-prioridad').value = t.priority;

    var pedidoBox = document.getElementById('adm-sop-d-pedido');
    if(t.pedido_id){
      sb.get('pedidos', 'id=eq.'+t.pedido_id+'&limit=1').then(function(peds){
        var p = peds && peds[0];
        if(p){
          pedidoBox.style.display = 'block';
          pedidoBox.innerHTML = '<b style="color:#1b87f5">Pedido relacionado #'+p.id+'</b><br/>'+_esc(p.producto)+' \u00b7 '+(ESTADO_LABEL[p.estado]?ESTADO_LABEL[p.estado].t:p.estado)+' \u00b7 '+_fechaPed(p.created_at);
        }
      });
    } else { pedidoBox.style.display = 'none'; }

    // Marcar como leido por el admin
    if(t.unread_admin) sb.patch('tickets', { unread_admin:false }, 'id=eq.'+ticketId).then(admSopCargarLista);

    admSopCargarMensajes(ticketId);
  });
}

function admSopCargarMensajes(ticketId){
  var feed = document.getElementById('adm-sop-d-feed');
  feed.innerHTML = '<div style="text-align:center;padding:1rem;color:var(--muted);font-size:.78rem">Cargando...</div>';
  sb.get('ticket_messages', 'ticket_id=eq.'+ticketId+'&order=created_at.asc').then(function(rows){
    if(!rows || !rows.length){ feed.innerHTML = ''; return; }
    feed.innerHTML = rows.map(function(m){
      // En la vista admin: "user" = ellos (izquierda), "bot"/"agent" = nosotros (derecha)
      var esNuestro = m.sender_type !== 'user';
      var clase = m.sender_type === 'bot' ? 'sop-msg bot' : (m.sender_type === 'agent' ? 'sop-msg me' : 'sop-msg agent');
      var label = m.sender_type === 'bot' ? '<div class="sop-msg-label bot">\uD83E\uDD16 IA</div>' : (m.sender_type === 'agent' ? '<div class="sop-msg-label" style="color:#111215">\uD83D\uDC64 '+_esc(m.sender_name)+'</div>' : '');
      var img = m.attachment_url ? '<img src="'+m.attachment_url+'" alt="adjunto"/>' : '';
      var fecha = m.created_at ? new Date(m.created_at).toLocaleString('es-MX',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}) : '';
      return '<div class="sop-msg-row '+(esNuestro?'me':'them')+'">'
        + '<div class="'+clase+'">'+label+_esc(m.message).replace(/\n/g,'<br/>')+img+'</div>'
        + '<div class="sop-msg-time">'+fecha+'</div>'
        + '</div>';
    }).join('');
    feed.scrollTop = feed.scrollHeight;
  });
}

function admSopResponder(){
  if(!_admSopTicketActual) return;
  var input = document.getElementById('adm-sop-d-input');
  var texto = (input.value||'').trim();
  if(!texto){ showToast('Escribe una respuesta'); return; }

  var ticketId = _admSopTicketActual;
  var agente = (authSession && authSession.username) || 'Admin';

  sb.post('ticket_messages', { ticket_id: ticketId, sender_type:'agent', sender_name: agente, message: texto }).then(function(){
    input.value = '';
    return sb.patch('tickets', { status:'en_atencion', unread_user:true, assigned_agent: agente }, 'id=eq.'+ticketId);
  }).then(function(){
    admSopCargarMensajes(ticketId);
    showToast('Respuesta enviada', 1800);
  }).catch(function(){ showToast('No se pudo enviar la respuesta'); });
}

function admSopCambiarEstado(nuevoEstado){
  if(!_admSopTicketActual) return;
  var data = { status: nuevoEstado };
  if(nuevoEstado === 'cerrado') data.closed_at = new Date().toISOString();
  sb.patch('tickets', data, 'id=eq.'+_admSopTicketActual).then(function(){
    showToast('Estado actualizado', 1500);
  }).catch(function(){ showToast('Error al cambiar estado'); });
}

function admSopCambiarPrioridad(nuevaPrioridad){
  if(!_admSopTicketActual) return;
  sb.patch('tickets', { priority: nuevaPrioridad }, 'id=eq.'+_admSopTicketActual).then(function(){
    showToast('Prioridad actualizada', 1500);
  }).catch(function(){ showToast('Error al cambiar prioridad'); });
}

/* ================================================================
   PANEL ADMIN — GESTIÓN DE USUARIOS INACTIVOS
================================================================ */
var _inactDiasActual = 7;
var _inactUsuarios = [];         // ultima lista cargada
var _inactSeleccion = {};        // {id: true} de los marcados

function admInactSetDias(dias){
  _inactDiasActual = dias;
  [7,14,21,30].forEach(function(d){
    var btn = document.getElementById('inact-f-'+d);
    if(btn) btn.className = 'inact-filtro-btn' + (d===dias ? ' active' : '');
  });
  admInactCargar();
}

function admInactCargar(){
  var body = document.getElementById('inact-tabla-body');
  var resumen = document.getElementById('inact-resumen');
  if(!body || !authSession) return;
  body.innerHTML = '<tr><td colspan="8" style="text-align:center;color:var(--muted);padding:1.5rem">Cargando...</td></tr>';
  _inactSeleccion = {};
  admInactActualizarBotonMasivo();
  var chkAll = document.getElementById('inact-check-all');
  if(chkAll) chkAll.checked = false;

  sb.rpc('listar_usuarios_inactivos', { p_admin_id: authSession.id, p_dias: _inactDiasActual }).then(function(rows){
    _inactUsuarios = rows || [];
    if(!_inactUsuarios.length){
      body.innerHTML = '<tr><td colspan="8" style="text-align:center;color:var(--muted);padding:1.5rem">No hay usuarios inactivos con ese filtro</td></tr>';
      if(resumen) resumen.textContent = 'Usuarios que no han usado la plataforma en los ultimos ' + _inactDiasActual + ' dias: 0';
      return;
    }
    if(resumen) resumen.textContent = 'Usuarios que no han usado la plataforma en los ultimos ' + _inactDiasActual + ' dias: ' + _inactUsuarios.length;

    body.innerHTML = _inactUsuarios.map(function(u){
      var dias = u.dias_inactivo || 0;
      var estadoClase = dias >= 30 ? 'candidato' : (dias >= 14 ? 'inactivo' : 'activo');
      var estadoTxt = dias >= 30 ? 'Candidato a eliminacion' : (dias >= 14 ? 'Inactivo' : 'Activo');
      var estadoIco = dias >= 30 ? '\uD83D\uDD34' : (dias >= 14 ? '\uD83D\uDFE1' : '\uD83D\uDFE2');
      var fechaReg = u.created_at ? new Date(u.created_at).toLocaleDateString('es-MX') : '-';
      var fechaVisto = u.last_seen ? new Date(u.last_seen).toLocaleDateString('es-MX') : '-';
      return '<tr>'
        + '<td><input type="checkbox" class="inact-check-row" data-id="'+u.id+'" onchange="admInactToggleUno(\''+u.id+'\',this.checked)" style="width:16px;height:16px;accent-color:#1b87f5"/></td>'
        + '<td>'+_esc(u.username)+(u.nombre?'<br/><span style="font-size:.68rem;color:var(--muted)">'+_esc(u.nombre)+'</span>':'')+'</td>'
        + '<td>'+fechaReg+'</td>'
        + '<td>'+fechaVisto+'</td>'
        + '<td>'+dias+' dias</td>'
        + '<td style="color:'+(u.saldo>0?'#25d366':'var(--muted)')+';font-weight:'+(u.saldo>0?'700':'400')+'">'+fmt(u.saldo||0)+'</td>'
        + '<td><span class="inact-estado inact-estado--'+estadoClase+'">'+estadoIco+' '+estadoTxt+'</span></td>'
        + '<td><button class="inact-del-btn" onclick="admInactConfirmarUno(\''+u.id+'\')">Eliminar</button></td>'
        + '</tr>';
    }).join('');
  }).catch(function(e){
    body.innerHTML = '<tr><td colspan="8" style="text-align:center;color:var(--muted);padding:1.5rem">Error al cargar (&#191;eres admin?)</td></tr>';
    console.error('[INACTIVOS]', e);
  });
}

function admInactToggleAll(marcar){
  document.querySelectorAll('.inact-check-row').forEach(function(chk){
    chk.checked = marcar;
    if(marcar) _inactSeleccion[chk.dataset.id] = true;
    else delete _inactSeleccion[chk.dataset.id];
  });
  admInactActualizarBotonMasivo();
}

function admInactToggleUno(id, marcado){
  if(marcado) _inactSeleccion[id] = true;
  else delete _inactSeleccion[id];
  admInactActualizarBotonMasivo();
}

function admInactActualizarBotonMasivo(){
  var btn = document.getElementById('inact-btn-masivo');
  var count = Object.keys(_inactSeleccion).length;
  if(!btn) return;
  if(count > 0){
    btn.disabled = false; btn.style.opacity = '1';
    btn.textContent = 'Eliminar seleccionados ('+count+')';
  } else {
    btn.disabled = true; btn.style.opacity = '.5';
    btn.textContent = 'Eliminar seleccionados';
  }
}

// ── Confirmación de eliminación INDIVIDUAL ──────────────────────
function admInactConfirmarUno(userId){
  var u = _inactUsuarios.find(function(x){ return x.id === userId; });
  if(!u) return;

  var tieneSaldo = (u.saldo||0) > 0;
  var overlay = document.createElement('div');
  overlay.style.cssText = 'position:fixed;inset:0;z-index:10000;background:rgba(0,0,0,.78);display:flex;align-items:center;justify-content:center;padding:1rem;backdrop-filter:blur(4px)';

  var advertenciaSaldo = tieneSaldo
    ? '<div style="background:rgba(255,80,80,.1);border:1px solid rgba(255,80,80,.35);border-radius:11px;padding:.8rem .9rem;margin:.9rem 0;font-size:.78rem;color:#ff9a9a;line-height:1.6"><b>&#9888;&#65039; Este usuario tiene '+fmt(u.saldo)+' de saldo.</b><br/>Si continuas, su cuenta y todos sus datos seran eliminados permanentemente. Esta accion no se puede deshacer.</div>'
    : '';

  var campoConfirmar = tieneSaldo
    ? '<div style="margin-top:.9rem"><label style="font-size:.72rem;color:#8b93a3;display:block;margin-bottom:.4rem">Escribe <b style="color:#ff6b6b">ELIMINAR</b> para confirmar</label><input id="inact-confirm-txt" type="text" class="finput" style="margin-bottom:0" placeholder="ELIMINAR"/></div>'
    : '';

  overlay.innerHTML = '<div style="background:#0d1117;border:1.5px solid rgba(255,80,80,.4);border-radius:18px;padding:1.5rem;max-width:380px;width:100%">'
    + '<div style="font-size:1.8rem;text-align:center;margin-bottom:.5rem">&#128465;&#65039;</div>'
    + '<div style="font-family:Saira;font-weight:900;font-size:1rem;color:#fff;text-align:center;margin-bottom:.5rem">Eliminar a '+_esc(u.username)+'</div>'
    + '<div style="font-size:.8rem;color:#8b93a3;text-align:center;line-height:1.6">Se borraran su perfil, pedidos, movimientos de saldo, likes enviados, tickets de soporte y resenas.</div>'
    + advertenciaSaldo
    + campoConfirmar
    + '<div style="display:flex;gap:.65rem;margin-top:1.2rem">'
    + '<button id="inact-cancel-btn" style="flex:1;padding:.75rem;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1);color:#8b93a3;border-radius:11px;font-family:Barlow;font-weight:700;font-size:.82rem;cursor:pointer">Cancelar</button>'
    + '<button id="inact-confirm-btn" style="flex:1;padding:.75rem;background:linear-gradient(135deg,#a30000,#ff6b6b);border:none;color:#fff;border-radius:11px;font-family:Saira;font-weight:900;font-size:.82rem;cursor:pointer">Eliminar</button>'
    + '</div></div>';

  document.body.appendChild(overlay);
  document.getElementById('inact-cancel-btn').onclick = function(){ overlay.remove(); };
  document.getElementById('inact-confirm-btn').onclick = function(){
    if(tieneSaldo){
      var txt = (document.getElementById('inact-confirm-txt').value || '').trim().toUpperCase();
      if(txt !== 'ELIMINAR'){ showToast('Escribe ELIMINAR para confirmar'); return; }
    }
    overlay.remove();
    admInactEjecutarBorrado([userId]);
  };
}

// ── Confirmación de eliminación MASIVA ──────────────────────────
function admInactConfirmarMasivo(){
  var ids = Object.keys(_inactSeleccion);
  if(!ids.length) return;
  var seleccionados = _inactUsuarios.filter(function(u){ return _inactSeleccion[u.id]; });
  var saldoTotal = seleccionados.reduce(function(s,u){ return s + (u.saldo||0); }, 0);

  var overlay = document.createElement('div');
  overlay.style.cssText = 'position:fixed;inset:0;z-index:10000;background:rgba(0,0,0,.78);display:flex;align-items:center;justify-content:center;padding:1rem;backdrop-filter:blur(4px)';
  overlay.innerHTML = '<div style="background:#0d1117;border:1.5px solid rgba(255,80,80,.4);border-radius:18px;padding:1.5rem;max-width:380px;width:100%">'
    + '<div style="font-size:1.8rem;text-align:center;margin-bottom:.5rem">&#128465;&#65039;</div>'
    + '<div style="font-family:Saira;font-weight:900;font-size:1rem;color:#fff;text-align:center;margin-bottom:.7rem">Eliminacion masiva</div>'
    + '<div style="font-size:.82rem;color:#c8d0e0;text-align:center;line-height:1.7">Vas a eliminar <b style="color:#fff">'+ids.length+' usuarios</b>.<br/>Saldo total de las cuentas: <b style="color:#ff6b6b">'+fmt(saldoTotal)+' MXN</b>.<br/><br/>Esta accion eliminara permanentemente sus cuentas y datos.</div>'
    + '<div style="margin-top:1rem"><label style="font-size:.72rem;color:#8b93a3;display:block;margin-bottom:.4rem">Escribe <b style="color:#ff6b6b">ELIMINAR</b> para confirmar</label><input id="inact-confirm-masivo-txt" type="text" class="finput" style="margin-bottom:0" placeholder="ELIMINAR"/></div>'
    + '<div style="display:flex;gap:.65rem;margin-top:1.2rem">'
    + '<button id="inact-cancel-masivo-btn" style="flex:1;padding:.75rem;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.1);color:#8b93a3;border-radius:11px;font-family:Barlow;font-weight:700;font-size:.82rem;cursor:pointer">Cancelar</button>'
    + '<button id="inact-confirm-masivo-btn2" style="flex:1;padding:.75rem;background:linear-gradient(135deg,#a30000,#ff6b6b);border:none;color:#fff;border-radius:11px;font-family:Saira;font-weight:900;font-size:.82rem;cursor:pointer">Eliminar todos</button>'
    + '</div></div>';

  document.body.appendChild(overlay);
  document.getElementById('inact-cancel-masivo-btn').onclick = function(){ overlay.remove(); };
  document.getElementById('inact-confirm-masivo-btn2').onclick = function(){
    var txt = (document.getElementById('inact-confirm-masivo-txt').value || '').trim().toUpperCase();
    if(txt !== 'ELIMINAR'){ showToast('Escribe ELIMINAR para confirmar'); return; }
    overlay.remove();
    admInactEjecutarBorrado(ids);
  };
}

// ── Ejecuta el borrado real, uno por uno, vía la función segura del servidor ──
function admInactEjecutarBorrado(ids){
  showToast('Eliminando '+ids.length+' cuenta(s)...', 3000);
  var completados = 0, errores = 0;

  function siguiente(i){
    if(i >= ids.length){
      showToast('Listo: '+completados+' eliminado(s)'+(errores?', '+errores+' con error':''), 3500);
      admInactCargar();
      return;
    }
    sb.rpc('eliminar_usuario_completo', { p_admin_id: authSession.id, p_target_id: ids[i] })
      .then(function(){ completados++; siguiente(i+1); })
      .catch(function(e){ errores++; console.error('[INACTIVOS] Error al borrar', ids[i], e); siguiente(i+1); });
  }
  siguiente(0);
}


function renderResenas(){
  var grid = document.getElementById('resenas-grid');
  if(!grid) return;
  // Top 3 fijo — nunca se agregan ni cargan mas reseñas
  grid.innerHTML = RESENAS_DEMO.map(_resenaCardHTML).join('');
}

function loadLiveStats(){
  sb.get('profiles','select=id').then(function(users){
    var el=document.getElementById('stats-users');
    if(el&&users&&Array.isArray(users)) el.textContent=users.length.toLocaleString('es-MX');
  }).catch(function(){});
  /* Count diamonds and likes from movimientos */
  sb.get('movimientos_saldo','tipo=eq.compra&select=descripcion,monto').then(function(movs){
    if(!movs||!Array.isArray(movs)) return;
    var diamonds=0, likes=0;
    movs.forEach(function(m){
      var d=(m.descripcion||'').toLowerCase();
      if(d.indexOf('diamante')>=0){
        /* Extract number from description */
        var match=d.match(/(\d[\d,]*)\s*diamante/);
        if(match) diamonds+=parseInt(match[1].replace(/,/g,''))||0;
        else diamonds+=100;
      }
      if(d.indexOf('like')>=0){
        var matchL=d.match(/(\d[\d,]*)\s*like/);
        if(matchL) likes+=parseInt(matchL[1].replace(/,/g,''))||0;
        else likes+=1000;
      }
    });
    /* Add base numbers so it doesn't look empty */
    diamonds=Math.max(diamonds+56000, 56000);
    likes=Math.max(likes+1500, 1500);
    var elD=document.getElementById('stats-diamonds');
    var elL=document.getElementById('stats-likes');
    if(elD) elD.textContent=diamonds.toLocaleString('es-MX');
    if(elL) elL.textContent=likes.toLocaleString('es-MX');
  }).catch(function(){});
  /* Rating from resenas */
  sb.get('resenas','select=stars').then(function(rows){
    if(!rows||!rows.length) return;
    var avg=(rows.reduce(function(s,r){return s+r.stars;},0)/rows.length).toFixed(1);
    var elR=document.getElementById('stats-rating');
    if(elR) elR.textContent=avg;
  }).catch(function(){});
}

/* Weekly report \u2014 every Monday */
(function(){
  var lastReport=localStorage.getItem('cs_weekly_report');
  var now=new Date();
  var isMonday=now.getDay()===1;
  var todayStr=now.toDateString();
  if(isMonday&&lastReport!==todayStr&&adminAuthed){
    localStorage.setItem('cs_weekly_report',todayStr);
    setTimeout(admSendReporte,5000);
  }
})();

