// Construye la lista de productos según el tipo

// ═══════════ RECARGAS AUTOMÁTICAS (Recargas América type=recharge) ═══════════
// package_id = el ID de Recargas América | precio = costo USD × 20 (redondeado)
var RECARGAS_AUTO = [
  { package_id:351, catalog_id:5,  sku:'FFCH100Z',  nombre:'100 Diamantes + 10 Bono',      diamantes:110,   costoUSD:0.6650, precioUSD:0.7754, precioMXN:14.50, precio:14.50,   img:'img/diam-100.png'  },
  { package_id:348, catalog_id:6,  sku:'FFCH310Z',  nombre:'310 Diamantes + 31 Bono',      diamantes:341,   costoUSD:1.9999, precioUSD:2.2642, precioMXN:42.34, precio:42.34,   img:'img/diam-310.png'  },
  { package_id:350, catalog_id:7,  sku:'FFCH520Z',  nombre:'520 Diamantes + 52 Bono',      diamantes:572,   costoUSD:3.3955, precioUSD:3.5722, precioMXN:66.80, precio:66.80,   img:'img/diam-520.png'  },
  { package_id:347, catalog_id:8,  sku:'FFCH1060Z', nombre:'1.060 Diamantes + 106 Bono',   diamantes:1166,  costoUSD:6.3089, precioUSD:6.5989, precioMXN:123.40, precio:123.40,  img:'img/diam-1060.png' },
  { package_id:346, catalog_id:9,  sku:'FFCH2180Z', nombre:'2.180 Diamantes + 218 Bono',   diamantes:2398,  costoUSD:12.5203, precioUSD:12.8797, precioMXN:240.85, precio:240.85,  img:'img/diam-2180.png' },
  { package_id:349, catalog_id:10, sku:'FFCH5600Z', nombre:'5.600 Diamantes + 560 Bono',   diamantes:6160,  costoUSD:31.8640, precioUSD:31.9529, precioMXN:597.52, precio:597.52,  img:'img/diam-5600.png' },
  { package_id:null, catalog_id:null, nombre:'11.200 Diamantes + 1.120 Bono', diamantes:12320, costoUSD:66.32, precio:1300, manual:true }
];
// Precios de los diamantes: en USD (precioUSD) y en MXN (precioMXN) son FIJOS y salen de tu lista de precios.
// Las demas monedas se convierten desde el precio en USD con el tipo de cambio del dia (al abrir y cada 6 horas).
// Con PRECIOS_MXN_FIJOS = false el MXN vuelve a calcularse cada dia: precioUSD x tipo de cambio.
var PRECIOS_MXN_FIJOS = true;
function recalcularPreciosDiamantes(){
  RECARGAS_AUTO.forEach(function(r){
    if(PRECIOS_MXN_FIJOS && r.precioMXN){ r.precio = r.precioMXN; return; }
    if(USD_MXN > 0 && r.precioUSD) r.precio = Math.round(r.precioUSD * USD_MXN * 100) / 100;
  });
}
recalcularPreciosDiamantes();



// Devuelve la imagen del diamante según la cantidad total
function _imgPorDiamantes(total){
  var mapa = {
    110:'img/diam-100.png', 341:'img/diam-310.png', 572:'img/diam-520.png',
    1166:'img/diam-1060.png', 2398:'img/diam-2180.png', 6160:'img/diam-5600.png'
  };
  return mapa[total] || null;
}

function _getDiamProductos(tipo){
  if(tipo === 'bonus'){
    // Con Bono (productos originales +20%)
    var arr = [];
    for(var k in BONUS_PLANES){
      if(BONUS_PLANES.hasOwnProperty(k)){
        var bp = BONUS_PLANES[k];
        arr.push({ key:k, nombre:bp.label, diamantes:bp.diamantes, precio:bp.precio, tipo:'bonus' });
      }
    }
    return arr;
  } else if(tipo === 'ilim'){
    // Ilimitado = recargas automáticas (Recargas América, directo al ID)
    return RECARGAS_AUTO.map(function(r){
      return {
        key:(r.manual?'man_':'auto_')+(r.package_id||r.diamantes),
        nombre:r.nombre, diamantes:r.diamantes, precio:r.precio, precioUSD:r.precioUSD,
        tipo:(r.manual?'manual':'auto'), package_id:r.package_id, catalog_id:r.catalog_id,
        badge:(r.manual?'MANUAL':'AUTO'),
        esPase:!!r.esPase,
        img:r.img || _imgPorDiamantes(r.diamantes)
      };
    });
  } else if(tipo === '1vez'){
    return PRODUCTS_1VEZ.map(function(p){
      return { key:'1vez_'+p.id, nombre:p.name+' Diamantes', diamantes:p.total, precio:p.prices[0], tipo:'1vez', badge:p.badge, img:_imgPorDiamantes(p.total) };
    });
  }
  return [];
}

function setDiamTipo(tipo){
  _diamTipoActual = tipo;
  ['ilim','1vez'].forEach(function(t){
    var btn = document.getElementById('dtab-'+t);
    if(btn) btn.classList.toggle('active', t===tipo);
  });
  // Avisos segun el tab
  var aviso1vez = document.getElementById('diam-1vez-aviso');
  if(aviso1vez) aviso1vez.style.display = (tipo === '1vez') ? 'block' : 'none';
  var avisoLatam = document.getElementById('diam-latam-aviso');
  if(avisoLatam) avisoLatam.style.display = (tipo === 'ilim') ? 'block' : 'none';
  // Volver al catálogo si estaba en detalle
  document.getElementById('diam-catalogo').style.display='';
  document.getElementById('diam-detalle').style.display='none';
  renderDiamCatalogo();
}

