// Ventana emergente de advertencia (Pase / Bonus)
function _mostrarAvisoModal(titulo, texto, color){
  var ov = document.getElementById('aviso-entrega-ov');
  if(ov) ov.remove();
  ov = document.createElement('div');
  ov.id = 'aviso-entrega-ov';
  ov.style.cssText = 'position:fixed;inset:0;z-index:9999;background:rgba(4,6,12,.72);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);display:flex;align-items:center;justify-content:center;padding:1.2rem;animation:avOvIn .25s ease';
  ov.onclick = function(e){ if(e.target===ov){ _cerrarAvisoModal(); } };
  document.body.appendChild(ov);

  // Helper de cierre con animacion
  window._cerrarAvisoModal = function(){
    var o = document.getElementById('aviso-entrega-ov');
    if(!o) return;
    o.style.animation = 'avOvOut .2s ease forwards';
    var card = o.querySelector('.av-card');
    if(card) card.style.animation = 'avCardOut .2s ease forwards';
    setTimeout(function(){ if(o) o.remove(); }, 200);
  };

  // Asegurar que existan los keyframes (una sola vez)
  if(!document.getElementById('av-modal-css')){
    var st = document.createElement('style');
    st.id = 'av-modal-css';
    st.textContent =
      '@keyframes avOvIn{from{opacity:0}to{opacity:1}}'
      + '@keyframes avOvOut{from{opacity:1}to{opacity:0}}'
      + '@keyframes avCardIn{0%{transform:translateY(24px) scale(.94);opacity:0}100%{transform:translateY(0) scale(1);opacity:1}}'
      + '@keyframes avCardOut{to{transform:translateY(10px) scale(.97);opacity:0}}'
      + '@keyframes avIcoPop{0%{transform:scale(.3);opacity:0}55%{transform:scale(1.12)}100%{transform:scale(1);opacity:1}}'
      + '@keyframes avRing{0%{transform:scale(.7);opacity:.6}100%{transform:scale(1.5);opacity:0}}'
      + '.av-btn{transition:transform .15s,filter .2s,box-shadow .2s}'
      + '.av-btn:hover{filter:brightness(1.1)}'
      + '.av-btn:active{transform:scale(.96)}';
    document.head.appendChild(st);
  }

  var c = document.createElement('div');
  c.className = 'av-card';
  c.style.cssText = 'position:relative;max-width:400px;width:100%;background:linear-gradient(165deg,#17181b,#0a0b12);border:1px solid '+color+'44;border-radius:24px;padding:2rem 1.5rem 1.6rem;text-align:center;box-shadow:0 24px 70px rgba(0,0,0,.6),0 0 50px '+color+'22,inset 0 1px 0 rgba(255,255,255,.05);animation:avCardIn .4s cubic-bezier(.2,.8,.3,1.1) both';
  c.innerHTML =
    // Icono con anillos animados
    '<div style="position:relative;width:78px;height:78px;margin:0 auto 1.1rem">'
    +   '<div style="position:absolute;inset:0;border-radius:50%;border:2px solid '+color+'55;animation:avRing 1.8s ease-out infinite"></div>'
    +   '<div style="position:absolute;inset:0;border-radius:50%;border:2px solid '+color+'55;animation:avRing 1.8s ease-out infinite 0.9s"></div>'
    +   '<div style="position:relative;width:78px;height:78px;border-radius:50%;background:linear-gradient(135deg,'+color+'2e,'+color+'14);border:1.5px solid '+color+'66;display:flex;align-items:center;justify-content:center;animation:avIcoPop .5s cubic-bezier(.2,.8,.3,1.3) both">'
    +     '<svg width="38" height="38" viewBox="0 0 24 24" fill="none" stroke="'+color+'" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>'
    +   '</div>'
    + '</div>'
    + '<div style="font-family:Saira,sans-serif;font-weight:900;font-size:1.2rem;color:'+color+';margin-bottom:.7rem;letter-spacing:.5px">'+titulo+'</div>'
    + '<div style="font-size:.86rem;color:#c5cad6;line-height:1.65;margin-bottom:1.5rem">'+texto+'</div>'
    + '<button class="av-btn" onclick="_cerrarAvisoModal()" style="width:100%;padding:.95rem;background:linear-gradient(135deg,'+color+',' +color+'cc);color:#06080f;border:none;border-radius:14px;font-family:Saira,sans-serif;font-weight:900;font-size:.92rem;letter-spacing:.5px;cursor:pointer;box-shadow:0 8px 24px '+color+'33">Entendido</button>';
  ov.appendChild(c);
}

// ═══ Renderiza las tarjetas de servicios (juegos / digital) desde SERVICES ═══
function _renderServiceCard(s){
  var disp = (s.estado === 'disponible');
  var est = SVC_ESTADO_LABEL[s.estado] || SVC_ESTADO_LABEL.buscando_proveedor;
  var visual = s.imagen
    ? '<div class="svc-img"><img src="'+s.imagen+'" alt="'+s.nombre+'" onerror="this.parentNode.classList.add(\'svc-img-fallback\')"/></div>'
    : '<div class="svc-img svc-img-fallback"><span class="svc-ico-big">'+s.icono+'</span></div>';
  var accion = disp
    ? 'goPage(\''+s.ruta+'\')'
    : 'clickServicioNoDisponible(\''+s.nombre.replace(/'/g,"")+'\')';
  return '<div class="svc-card'+(disp?' svc-card--on':' svc-card--off')+'" onclick="'+accion+'">'
    + visual
    + '<div class="svc-body">'
    +   '<div class="svc-top"><span class="svc-name">'+s.icono+' '+s.nombre+'</span>'+(disp?'<span class="svc-tag" style="color:#25d366;border-color:#25d36644;background:#25d36614">&#128994; CAT&Aacute;LOGO DISPONIBLE</span>':'<span class="svc-tag" style="color:'+est.color+';border-color:'+est.color+'44;background:'+est.color+'14">'+est.ico+' '+est.txt+'</span>')+'</div>'
    +   '<div class="svc-desc">'+s.descripcion+'</div>'
    +   '<div class="svc-foot">'+(disp?'<span class="svc-cta">RECARGAR &#8594;</span>':'<span class="svc-cta svc-cta--off">VER MAS &#8594;</span>')+'</div>'
    + '</div>'
    + '</div>';
}

// Pastilla ovalada compacta (solo texto): usada en "Proximamente" y "Redes Sociales / Servicios Digitales"
function _renderServicePill(s){
  var disp = (s.estado === 'disponible');
  var accion = disp
    ? 'goPage(\''+s.ruta+'\')'
    : 'clickServicioNoDisponible(\''+s.nombre.replace(/'/g,"")+'\')';
  return '<div class="svc-pill'+(disp?' svc-pill--on':' svc-pill--off')+'" onclick="'+accion+'">'+s.icono+' '+s.nombre+'</div>';
}

function renderServiciosHome(){
  try{
  var wrapDestacados = document.getElementById('svc-videojuegos');
  var wrapProximWrap = document.getElementById('svc-proximamente-wrap');
  var wrapDigital = document.getElementById('svc-digital');

  var juegos = SERVICES.filter(function(s){ return s.categoria==='videojuegos'; });

  // Destacados: PUBG Mobile, COD Mobile, Roblox (Free Fire ya tiene su propio hero arriba, no se duplica aqui)
  // Destacados: Free Fire primero (imagen real, catalogo disponible), luego PUBG, COD, Roblox
  var nombresDestacados = ['Free Fire','PUBG','COD Mobile','Roblox'];
  var destacados = nombresDestacados.map(function(n){ return juegos.find(function(s){ return s.nombre===n; }); }).filter(Boolean);
  var resto = juegos.filter(function(s){ return nombresDestacados.indexOf(s.nombre) === -1; });

  if(wrapDestacados) wrapDestacados.innerHTML = destacados.map(_renderServiceCard).join('');

  if(wrapProximWrap && resto.length){
    wrapProximWrap.style.display = 'flex';
    wrapProximWrap.innerHTML = resto.map(_renderServicePill).join('');
  }

  if(wrapDigital){
    var digital = SERVICES.filter(function(s){ return s.categoria==='digital'; });
    wrapDigital.innerHTML = digital.map(_renderServicePill).join('');
  }
  }catch(e){
    console.error('[renderServiciosHome] Error:', e);
    var w = document.getElementById('svc-videojuegos');
    if(w) w.innerHTML = '<div style="text-align:center;padding:1.5rem;color:#ff6b6b;font-size:.75rem;grid-column:1/-1">Error al cargar el catalogo</div>';
  }
}

// Reintento: si el DOM del home ya existe al cargar el script (sin pasar por goPage), renderizar igual.
(function _svcAutoInit(){
  function tryRender(){
    if(document.getElementById('svc-videojuegos')) renderServiciosHome();
  }
  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', tryRender);
  } else {
    tryRender();
  }
})();

function abrirDiamDetalle(idx){
  var productos = _getDiamProductos(_diamTipoActual);
  var p = productos[idx];
  if(!p) return;
  _diamSeleccionado = p;
  _diamMetodoPago = 'saldo';

  // Ventana de advertencia segun el producto
  if(p.esPase){
    setTimeout(function(){
      _mostrarAvisoModal('ENTREGA POR REGALO',
        'El pase se manda mediante <b style="color:#fff">REGALO</b>.<br/><br/>Puede que te llegue de <b style="color:#fff">1 a 4 dias</b>.<br/>Consulta con el administrador.',
        '#ffb84d');
    }, 250);
  } else if(p.tipo==='bonus'){
    setTimeout(function(){
      _mostrarAvisoModal('TIEMPO DE ENTREGA',
        'Las recargas con <b style="color:#fff">bono</b> pueden llegar entre <b style="color:#fff">1 y 3 horas</b>.',
        '#ffb84d');
    }, 250);
  }

  var saldo = (authSession && authSession.saldo) ? authSession.saldo : 0;
  var alcanza = saldo >= p.precio;

  var det = document.getElementById('diam-detalle');
  det.innerHTML =
    '<button class="ddet-back" onclick="cerrarDiamDetalle()" style="background:none;border:none;color:#6b7280;font-size:.85rem;cursor:pointer;margin-bottom:1rem;padding:0">&#8592; Volver al catalogo</button>'
    + '<div style="background:rgba(255,255,255,.022);border:1px solid rgba(255,255,255,.065);border-radius:18px;padding:1.35rem">'
    + (p.img ? '<img src="'+p.img+'" alt="'+p.nombre+'" style="width:150px;display:block;margin:0 auto 1rem;border-radius:12px" onerror="this.style.display=\'none\'"/>' : '')
    + '<div style="text-align:center;margin-bottom:1.15rem">'
    +   '<div style="font-family:Barlow,sans-serif;font-weight:700;font-size:1.15rem;color:#fff;margin-bottom:.2rem">'+p.nombre+'</div>'
    +   '<div style="font-family:Barlow,sans-serif;font-weight:700;font-size:1.9rem;color:#fff">'+fmtDiam(p)+'</div>'
    +   '<div style="font-size:.78rem;color:#6b7280;margin-top:.15rem">Pago con saldo</div>'
    + '</div>'
    + _avisoEntrega(p)
    + '<label class="flabel">Tu ID de Free Fire *</label>'
    + '<input class="finput" id="diam-ffid" type="text" inputmode="numeric" placeholder="Ej: 123456789"/>'
    + '<div style="display:flex;justify-content:space-between;background:rgba(27,135,245,.05);border:1px solid rgba(27,135,245,.15);border-radius:11px;padding:.65rem 1rem;margin:.3rem 0 .8rem"><span style="font-size:.76rem;color:#6b7280">Tu saldo</span><span style="font-weight:600;color:'+(alcanza?'#1b87f5':'#ff6b6b')+';font-size:.85rem">'+fmt(saldo)+'</span></div>'
    + (alcanza ? '' : '<div style="background:rgba(255,60,60,.08);border:1px solid rgba(255,60,60,.25);border-radius:10px;padding:.65rem .85rem;font-size:.77rem;color:#ff6b6b;margin-bottom:.75rem">Saldo insuficiente. <span onclick="goPage(\'saldo\')" style="text-decoration:underline;cursor:pointer">Recarga aqui</span></div>')
    + '<div class="ddet-msg" id="diam-msg"></div>'
    + '<button id="diam-btn" onclick="confirmarDiamCompra()" style="width:100%;padding:.9rem;background:rgba(27,135,245,.12);border:1px solid rgba(27,135,245,.42);color:#1b87f5;border-radius:13px;font-family:Barlow;font-weight:600;font-size:.92rem;cursor:pointer">Comprar con saldo</button>'
    + '</div>';

  document.getElementById('diam-catalogo').style.display='none';
  det.style.display='';
  _actualizarDiamBoton();
}

function cerrarDiamDetalle(){
  document.getElementById('diam-detalle').style.display='none';
  document.getElementById('diam-catalogo').style.display='';
}

function selDiamMetodo(metodo){
  _diamMetodoPago = metodo;
  var s=document.getElementById('dm-saldo'), b=document.getElementById('dm-binance');
  if(s) s.classList.toggle('sel', metodo==='saldo');
  if(b) b.classList.toggle('sel', metodo==='binance');
  _actualizarDiamBoton();
}

function _actualizarDiamBoton(){
  var btn=document.getElementById('diam-btn');
  var msg=document.getElementById('diam-msg');
  if(!btn||!_diamSeleccionado) return;
  var saldo=(authSession&&authSession.saldo)?authSession.saldo:0;

  if(_diamMetodoPago==='saldo'){
    if(saldo>=_diamSeleccionado.precio){
      btn.className='ddet-btn on'; btn.innerHTML='Recargar con saldo &#8594;';
      if(msg){ msg.textContent=''; msg.className='ddet-msg'; }
    } else {
      btn.className='ddet-btn off';
      btn.innerHTML='Recargar con saldo &#8594;';
      if(msg){ msg.textContent='Saldo insuficiente para pagar con saldo. Usa Binance o recarga tu saldo.'; msg.className='ddet-msg err'; }
    }
  } else {
    btn.className='ddet-btn on'; btn.innerHTML='Pagar con Binance &#8594;';
    if(msg){ msg.textContent=''; msg.className='ddet-msg'; }
  }
}

var _comprandoDiam = false; // candado anti-doble-compra

function confirmarDiamCompra(){
  if(!authSession){ showToast('Inicia sesion para comprar'); setTimeout(showAuthModal,600); return; }

  // Evitar doble clic / doble pedido
  if(_comprandoDiam){ return; }

  var p=_diamSeleccionado;
  if(!p) return;
  var ffId=((document.getElementById('diam-ffid')||{}).value||'').trim();
  if(!ffId){ showToast('Escribe tu ID de Free Fire'); return; }

  var saldo=(authSession&&authSession.saldo)?authSession.saldo:0;

  if(saldo < p.precio){ showToast('Saldo insuficiente. Recarga primero.'); return; }

  // ═══ RECARGA AUTOMÁTICA (productos type=auto) ═══
  if(p.tipo === 'auto' && p.package_id){
    _procesarRecargaAutomatica(p, ffId);
    return;
  }

  // Activar candado y deshabilitar el botón
  _comprandoDiam = true;
  var btn = document.getElementById('diam-btn');
  if(btn){ btn.className='ddet-btn off'; btn.innerHTML='Procesando...'; }

  // Compra normal (ilimitados / 1vez): pedido manual
  var ord=getNextOrder();
  addSpend(p.precio, p.diamantes+' Diamantes ('+p.tipo+') - ID:'+ffId+' - Pedido #'+ord);
  registrarPedido(p.nombre, p.diamantes, 'diamantes', ffId, p.precio, 0);
  if(typeof tgNotifyPurchase==='function') tgNotifyPurchase(authSession.username, p.nombre+' - ID:'+ffId, p.precio, ord);
  _mostrarReciboProceso(p, ffId, ord);
  showToast('\u2705 Pedido #'+ord+' realizado!', 3000);

  // Liberar el candado después de un momento
  setTimeout(function(){ _comprandoDiam = false; }, 3000);
}

// ═══ Recibo "en proceso" con barra para compras normales ═══
function _mostrarReciboProceso(p, ffId, ord){
  var det = document.getElementById('diam-detalle');
  if(!det) return;

  var ahora = new Date();
  var fecha = ahora.toLocaleDateString('es-MX', { day:'2-digit', month:'2-digit', year:'numeric' });
  var hora = ahora.toLocaleTimeString('es-MX', { hour:'2-digit', minute:'2-digit' });

  det.innerHTML =
    '<div style="background:linear-gradient(160deg,rgba(255,180,60,.08),rgba(255,255,255,.02));border:2px solid rgba(255,180,60,.35);border-radius:18px;padding:1.75rem 1.35rem;text-align:center;max-width:420px;margin:0 auto">'
    + '<div style="font-size:2.8rem;margin-bottom:.5rem">\u23F3</div>'
    + '<div style="font-family:Saira;font-weight:900;font-size:1.25rem;color:#1b87f5;margin-bottom:.35rem;letter-spacing:.5px">RECARGA EN PROCESO</div>'
    + '<div style="font-size:.8rem;color:var(--muted);margin-bottom:1.35rem">Tu pedido se esta procesando, te lo acreditamos pronto</div>'

    // Barra de progreso animada
    + '<div style="background:rgba(0,0,0,.25);border-radius:99px;height:10px;overflow:hidden;margin-bottom:1.5rem">'
    +   '<div id="recibo-barra" style="height:100%;width:15%;border-radius:99px;background:linear-gradient(90deg,#1b87f5,#ff9900,#1b87f5);background-size:200% 100%;box-shadow:0 0 12px rgba(255,180,60,.5);transition:width .8s ease"></div>'
    + '</div>'

    + '<div style="background:rgba(0,0,0,.25);border:1px solid rgba(255,255,255,.08);border-radius:12px;padding:1rem;text-align:left">'
    +   _filaRecibo('\uD83D\uDCCB Pedido', '#'+ord)
    +   _filaRecibo('\uD83D\uDC8E Cantidad', p.nombre)
    +   _filaRecibo('\uD83C\uDFAE ID Free Fire', ffId)
    +   _filaRecibo('\uD83D\uDCB5 Precio', fmtDiam(p))
    +   _filaRecibo('\uD83D\uDCC5 Fecha', fecha + ' \u00B7 \uD83D\uDD52 ' + hora, true)
    + '</div>'

    + '<button onclick="cerrarDiamDetalle()" style="width:100%;margin-top:1.25rem;padding:.9rem;background:linear-gradient(135deg,#0a4fa8,#f0b90b);color:#fff;border:none;border-radius:12px;font-family:Barlow;font-weight:700;font-size:.9rem;cursor:pointer">Volver al catalogo</button>'
    + '</div>';

  det.style.display = '';
  document.getElementById('diam-catalogo').style.display = 'none';
  det.scrollIntoView({ behavior:'smooth', block:'center' });

  // Animar la barra (avanza gradualmente)
  setTimeout(function(){ var b=document.getElementById('recibo-barra'); if(b) b.style.width='55%'; }, 400);
  setTimeout(function(){ var b=document.getElementById('recibo-barra'); if(b) b.style.width='80%'; }, 1500);
}

// ═══ Genera el HTML de un estado de recarga: pending / ok / err ═══
function _rcEstadoHTML(tipo, titulo, sub){
  var iconos = { pending:'\u23F3', ok:'\u2705', err:'\u274C' };
  var ico = iconos[tipo] || '\u23F3';
  var barra = (tipo === 'pending') ? '<div class="rc-bar"></div>' : '';
  return '<div class="rc-state rc-state--'+(tipo==='ok'?'ok':tipo==='err'?'err':'pending')+'">'
    + '<div class="rc-state-head"><span class="rc-state-ico">'+ico+'</span><span class="rc-state-title">'+titulo+'</span></div>'
    + '<div class="rc-state-sub">'+sub+'</div>'
    + barra
    + '</div>';
}

// ═══ Procesar recarga automática: valida ID → cobra saldo → recarga ═══
function _procesarRecargaAutomatica(p, ffId){
  if(_comprandoDiam){ return; }
  _comprandoDiam = true;
  var btn = document.getElementById('diam-btn');
  var msg = document.getElementById('diam-msg');
  if(btn){ btn.disabled=true; btn.className='ddet-btn off'; btn.innerHTML='<span class="rc-spin"></span> Verificando saldo...'; }
  if(msg){ msg.className='ddet-msg'; msg.innerHTML = _rcEstadoHTML('pending', '\u23F3 RECARGA EN PROCESO', 'Estamos verificando tu saldo, por favor espera...'); }

  // Paso 0: verificar saldo REAL en Supabase (protege contra pagina vieja/no actualizada)
  verificarSaldoFresco(p.precio, function(alcanza, saldoReal){
    if(!alcanza){
      if(btn){ btn.disabled=false; btn.className='ddet-btn on'; btn.innerHTML='Recargar con saldo &#8594;'; }
      if(msg){ msg.className='ddet-msg'; msg.innerHTML = _rcEstadoHTML('err', 'SALDO INSUFICIENTE', 'Tu saldo real es <b style="color:#fff">'+fmt(saldoReal)+'</b>. <span onclick="goPage(\'saldo\')" style="text-decoration:underline;cursor:pointer;color:#ff6b6b">Recarga aqui</span>'); }
      _comprandoDiam = false;
      return;
    }
    if(btn){ btn.innerHTML='<span class="rc-spin"></span> Validando ID...'; }
    if(msg){ msg.innerHTML = _rcEstadoHTML('pending', '\u23F3 RECARGA EN PROCESO', 'Validando tu ID de Free Fire, por favor espera...'); }

  // Paso 1: validar que el ID exista
  fetchRecargaAuto(COMPRAR_RECARGA_URL, {
    method:'POST', headers:{'Content-Type':'application/json'},
    body: JSON.stringify({ action:'validar', product_id:p.package_id, service_user_id:ffId })
  }).then(function(r){ return r.json(); }).then(function(val){
    if(!val.success || !val.valido){
      // ID NO VERIFICADO: no bloquear. Mostrar advertencia clara y pedir confirmacion explicita.
      if(btn){ btn.disabled=false; }
      _mostrarConfirmacionIdNoVerificado(p, ffId, btn, msg);
      console.warn('[RECARGA] ID no verificado:', JSON.stringify(val));
      _comprandoDiam = false;
      return;
    }

    // ID válido: mostrar nombre y confirmar
    var nombre = val.nombre || 'Jugador';
    if(msg){ msg.innerHTML = _rcEstadoHTML('pending', '\u23F3 RECARGA EN PROCESO', 'Cuenta encontrada: <b style="color:#fff">'+nombre+'</b><br/>Procesando tu recarga, por favor espera...'); }
    if(btn){ btn.innerHTML='<span class="rc-spin"></span> Recargando...'; }
    _ejecutarRecargaVerificada(p, ffId, nombre, 'verified', btn, msg);
  }).catch(function(err){
    if(btn){ btn.disabled=false; btn.className='ddet-btn on'; btn.innerHTML='Recargar con saldo &#8594;'; }
    if(msg){ msg.className='ddet-msg'; msg.innerHTML = _rcEstadoHTML('err', 'ERROR DE CONEXION', 'No pudimos validar tu ID. Verifica tu conexion e intenta de nuevo.'); }
    console.error('[RECARGA] catch validar:', err);
    _comprandoDiam = false;
  });

  }); // fin verificarSaldoFresco
}

// ═══ Ejecuta el cobro + recarga real contra el proveedor.
// verificationStatus: 'verified' | 'unverified' — nunca inventa nombre de jugador
// cuando es unverified; el ID que se envia al proveedor es EXACTAMENTE el que
// escribio el usuario, sin modificarlo. ═══
function _ejecutarRecargaVerificada(p, ffId, nombre, verificationStatus, btn, msg){
  var esVerificado = (verificationStatus === 'verified');
  var etiquetaJugador = esVerificado ? (' ('+nombre+')') : ' (SIN VERIFICAR)';

  // Paso 2: cobrar el saldo AHORA (antes de recargar)
  var ord=getNextOrder();
  var _movCompraId = null;              // ID del movimiento (para cancelarlo si falla)
  var _cancelarPendiente = false;       // si la recarga falla antes de tener el ID
  addSpend._onMovId = function(id){
    _movCompraId = id;
    // Si la recarga ya habia fallado, cancelar ahora que tenemos el ID
    if(_cancelarPendiente) _cancelarMovPorId(id);
  };
  addSpend(p.precio, p.diamantes+' Diamantes (Recarga AUTO '+p.nombre+') - ID:'+ffId+etiquetaJugador+' - Pedido #'+ord);

  // Idempotency key: se genera UNA VEZ por pedido (no en cada llamada de red). Si este
  // mismo pedido necesitara reintentarse (ej: el admin lo reintenta manual desde el
  // panel), debe reenviarse esta MISMA clave — nunca generar una nueva — para que el
  // proveedor detecte el duplicado en vez de cobrar dos veces por la misma recarga.
  var idempotencyKey = (typeof crypto !== 'undefined' && crypto.randomUUID) ? crypto.randomUUID() : ('cs-'+ord+'-'+Date.now());

  // Paso 3: hacer la recarga automática — SIEMPRE con el ffId exacto que escribio el usuario
  fetchRecargaAuto(COMPRAR_RECARGA_URL, {
    method:'POST', headers:{'Content-Type':'application/json'},
    body: JSON.stringify({ action:'comprar', package_id:p.package_id, catalog_id:p.catalog_id, sku:p.sku, player_id:ffId, client_name:authSession.username, idempotency_key:idempotencyKey })
  }).then(function(r){ return r.json(); }).then(function(res){
    if(res.success && (res.status==='COMPLETED' || res.status==='PENDING')){
      registrarPedido(p.nombre+' (AUTO'+(esVerificado?'':' - ID NO VERIFICADO')+')', p.diamantes, 'diamantes', ffId, p.precio, 0, {res:res, ord:ord, diamantes:p.diamantes});
      if(typeof tgNotifyPurchase==='function'){
        var infoJugador = esVerificado ? ('\uD83D\uDC64 Nombre IG: '+nombre) : '\u26A0\uFE0F ID SIN VERIFICAR - cliente confirmo bajo su responsabilidad';
        var infoVia = res.via ? ('\n\uD83D\uDD17 Via: '+(res.via==='catalog'?'Catalogo Unificado':(res.via&&String(res.via).indexOf('Central One')===0?res.via:'API pines'))) : '';
        tgNotifyPurchase(authSession.username, '\u26A1 Recarga AUTO\n\uD83D\uDCA0 Paquete: '+p.nombre+'\n\uD83C\uDFAE ID: '+ffId+'\n'+infoJugador+infoVia+(typeof csGananciaTxt==='function'?csGananciaTxt(p.precio,p.precioUSD,res.costo_usd,res.status):''), p.precio, ord);
      }
      // Puntos de ranking: SOLO cuando el proveedor confirma COMPLETED de verdad.
      // PENDING no otorga puntos (regla explicita) — si mas tarde se marca
      // COMPLETED por otro medio, otorgar_puntos_pedido() puede llamarse de nuevo
      // con el mismo pedido_id sin duplicar (UNIQUE lo protege).
      if(res.status==='COMPLETED' && typeof sb!=='undefined' && sb.rpc && authSession && authSession.id){
        (csRegistrarVentaDiamantes(authSession.id, ord, p.diamantes, p.precio), sb.rpc('otorgar_puntos_pedido', { p_user_id: authSession.id, p_pedido_id: ord, p_diamantes: p.diamantes }))
          .then(function(pts){ if(pts) console.log('[PUNTOS] +'+pts+' puntos otorgados, pedido #'+ord); })
          .catch(function(e){ console.error('[PUNTOS] Error otorgando:', e); });
      }
      _mostrarReciboRecarga(p, ffId, esVerificado ? nombre : null, res.status);
      var txt = res.status==='COMPLETED' ? '\u2705 Recarga COMPLETADA!' : '\u23F3 Recarga en proceso...';
      showToast(txt, 3000);
      _comprandoDiam = false;
    } else {
      var errTxt = String(res.error||res.status||('sin confirmar · respuesta: '+(function(){try{return JSON.stringify(res).slice(0,220);}catch(e){return '?';}})()));
      var errCode = String(res.code||'');
      // La Edge Function nueva devuelve un "code" explicito del proveedor
      // (PURCHASE_FAILED, PRODUCT_INACTIVE, PROVIDER_ERROR, DUPLICATE_REQUEST,
      // ENDPOINT_DISABLED). Ese code es la fuente de verdad; el regex de texto
      // solo cubre el caso de una version vieja de la funcion que aun no mande "code".
      // ENDPOINT_DISABLED significa que la ruta HTTP fue rechazada ANTES de tocar
      // el proveedor (404, ruta inexistente) — nunca se llego a cobrar nada, es
      // igual de seguro reembolsar que con PURCHASE_FAILED/PRODUCT_INACTIVE.
      var sinFondos = (errCode==='PURCHASE_FAILED' || errCode==='PRODUCT_INACTIVE' || errCode==='ENDPOINT_DISABLED') ||
        (!errCode && /saldo insuficiente|insufficient|fondos insuficientes|sin fondos|credito insuficiente|balance too low|no balance|limite excedido|limit exceeded/i.test(errTxt));
      var noDisponible = (!errCode && /no disponible|not available|no encontrado|not found|sin stock|out of stock/i.test(errTxt));
      // PROVIDER_ERROR: el proveedor SI fue contactado - nunca reembolsar automatico,
      // siempre dejar para revision manual (igual que el bloque de "error ambiguo" abajo).
      var proveedorContactado = (errCode === 'PROVIDER_ERROR');
      var esDuplicado = (errCode === 'DUPLICATE_REQUEST');

      if(esDuplicado){
        // Esta misma idempotency_key ya se habia usado — no asumir nada, dejar
        // en revision manual para que el admin consulte el estado real primero.
        registrarPedido(p.nombre+' (AUTO - DUPLICADA, VERIFICAR)', p.diamantes, 'diamantes', ffId, p.precio, 0, {ord:ord});
        if(typeof tgNotifyPurchase==='function') tgNotifyPurchase(authSession.username, '\u26A0\uFE0F PEDIDO DUPLICADO (idempotencia) - Recarga AUTO\n\uD83D\uDCA0 Paquete: '+p.nombre+'\n\uD83C\uDFAE ID: '+ffId+'\n\u2757 '+errTxt+'\n\uD83D\uDD11 Key: '+idempotencyKey, p.precio, ord);
        if(btn){ btn.disabled=false; btn.className='ddet-btn on'; btn.innerHTML='Recargar con saldo &#8594;'; }
        if(msg){ msg.className='ddet-msg'; msg.innerHTML = _rcEstadoHTML('pending', '\u23F3 EN VERIFICACION', 'Este pedido parece repetido. Estamos verificando el estado real antes de continuar.'); }
        console.warn('[RECARGA] Duplicado (no reembolsado, revision manual):', JSON.stringify(res));
        _comprandoDiam = false;
        return;
      }

      if(proveedorContactado){
        // El proveedor fue contactado (con exito o no) - la wallet mayorista ya se
        // movio. Nunca reembolsar solo: dejar para revision manual, igual que el
        // bloque de "error ambiguo" que ya existia.
        registrarPedido(p.nombre+' (AUTO - VERIFICAR)', p.diamantes, 'diamantes', ffId, p.precio, 0, {ord:ord});
        if(typeof tgNotifyPurchase==='function') tgNotifyPurchase(authSession.username, '\u26A0\uFE0F PROVEEDOR CONTACTADO, VERIFICAR - Recarga AUTO\n\uD83D\uDCA0 Paquete: '+p.nombre+'\n\uD83C\uDFAE ID: '+ffId+'\n\u2757 '+errTxt+'\n\uD83D\uDD11 Key: '+idempotencyKey, p.precio, ord);
        if(btn){ btn.disabled=false; btn.className='ddet-btn on'; btn.innerHTML='Recargar con saldo &#8594;'; }
        if(msg){ msg.className='ddet-msg'; msg.innerHTML = _rcEstadoHTML('pending', '\u23F3 EN VERIFICACION', 'Tu recarga se esta verificando. Si no llega en unos minutos, contacta al admin con tu ID.'); }
        console.error('[RECARGA] Proveedor contactado (no reembolsado, revision manual):', JSON.stringify(res));
        _comprandoDiam = false;
        setTimeout(cerrarDiamDetalle, 4000);
        return;
      }

      if(sinFondos){
        // RECARGA RECHAZADA: devolver el saldo y avisar al admin con urgencia.
        // IMPORTANTE: el mensaje a Telegram debe reflejar si el reembolso REAL
        // se completo o no — antes se avisaba "reembolsado" sin condicion,
        // aunque el RPC hubiera fallado, y el dinero se quedaba sin devolver.
        _rpcAjustarSaldo(authSession.id, p.precio).then(function(saldoNuevo){
          var sn = Number(saldoNuevo)||0;
          authSession.saldo = sn;
          _refreshSaldoUI(sn);
          if(typeof saveSession==='function') saveSession(authSession);
          if(typeof sbAddMovimiento==='function') sbAddMovimiento(authSession.id, 'credito', p.precio, 'Reembolso Pedido #'+ord+' - recarga rechazada');
          if(_movCompraId) _cancelarMovPorId(_movCompraId); else { _cancelarPendiente = true; _cancelarMovimientoCompra(authSession.id, ord); }

          registrarPedido(p.nombre+' (RECHAZADA - reembolsado)', p.diamantes, 'diamantes', ffId, 0, 0, {estado:'rechazado', ord:ord});
          // Reversion de seguridad: si por algun motivo este pedido ya habia
          // otorgado puntos antes, los revierte. Si nunca otorgo puntos (caso
          // normal aqui), el RPC simplemente devuelve 0 sin hacer nada.
          if(typeof sb!=='undefined' && sb.rpc && authSession && authSession.id){
            csAnularVentaDiamantes(authSession.id, ord); sb.rpc('revertir_puntos_pedido', { p_user_id: authSession.id, p_pedido_id: ord, p_motivo: 'Recarga rechazada - sin fondos del proveedor' }).catch(function(){});
          }
          if(typeof tgNotifyPurchase==='function') tgNotifyPurchase(authSession.username, '\uD83D\uDEA8 <b>RECARGA RECHAZADA - '+(/desactualizada/i.test(errTxt)?'CLIENTE CON VERSION ANTIGUA':(/pausa|l[i\u00ED]mite|por hora/i.test(errTxt)?'LIMITE DE GASTO ALCANZADO':'SIN FONDOS'))+'</b>\n\uD83D\uDCA0 Paquete: '+p.nombre+'\n\uD83C\uDFAE ID: '+ffId+'\n\u2757 '+errTxt+'\n\u2705 Saldo reembolsado al cliente ('+fmt(p.precio)+')\n\n\u26A0\uFE0F <b>'+(/desactualizada/i.test(errTxt)?'SIN ACCION: el cliente debe actualizar la pagina (ya se le devolvio el saldo)':(/pausa|l[i\u00ED]mite|por hora/i.test(errTxt)?'SUBE EL TOPE EN VERCEL: CO_LIMITE_DIA_USD / CO_LIMITE_USUARIO_HORA':'RECARGA TU CUENTA DEL PROVEEDOR'))+'</b>', p.precio, ord);
        }).catch(function(e){
          // El reembolso NO se pudo completar — el cliente SIGUE sin su dinero.
          // No decir "reembolsado" en Telegram: avisar con urgencia real para
          // que el admin lo reembolse manualmente.
          console.error('[RECARGA] reembolso fallo:', e);
          registrarPedido(p.nombre+' (RECHAZADA - REEMBOLSO FALLIDO, REVISAR)', p.diamantes, 'diamantes', ffId, p.precio, 0, {ord:ord});
          if(typeof tgNotifyPurchase==='function') tgNotifyPurchase(authSession.username, '\uD83D\uDD25 <b>URGENTE: REEMBOLSO FALLIDO</b>\n\uD83D\uDCA0 Paquete: '+p.nombre+'\n\uD83C\uDFAE ID: '+ffId+'\n\u2757 Recarga rechazada: '+errTxt+'\n\u274C El reembolso automatico de '+fmt(p.precio)+' AL CLIENTE FALLO ('+String((e&&e.message)||e)+')\n\n\uD83D\uDEA8 <b>REEMBOLSA MANUALMENTE AL CLIENTE Y RECARGA TU CUENTA DEL PROVEEDOR</b>', p.precio, ord);
        });

        if(btn){ btn.disabled=false; btn.className='ddet-btn on'; btn.innerHTML='Recargar con saldo &#8594;'; }
        if(msg){ msg.className='ddet-msg'; msg.innerHTML = _rcEstadoHTML('err', 'RECARGA RECHAZADA', 'Contacta al administrador. <b style="color:#fff">Tu saldo sera reembolsado.</b>'); }

        if(typeof _mostrarAvisoModal==='function'){
          _mostrarAvisoModal('RECARGA RECHAZADA',
            'No pudimos completar tu recarga en este momento.<br/><br/><b style="color:#fff">Contacta al administrador.</b><div style="margin-top:1.1rem;padding:.8rem 1rem;background:rgba(37,211,102,.1);border:1px solid rgba(37,211,102,.3);border-radius:12px;display:flex;align-items:center;gap:.55rem;justify-content:center"><span style="font-size:1.1rem">\u2705</span><span style="font-size:.82rem;color:#25d366;font-weight:700">Tu saldo fue reembolsado automaticamente</span></div>',
            '#ff6b6b');
        }
        showToast('\u274C Recarga rechazada. Saldo reembolsado.', 5000);
        _comprandoDiam = false;
      } else if(noDisponible){
        // La recarga NO se hizo (producto no disponible): DEVOLVER el saldo automatico.
        // Mismo arreglo que arriba: solo avisar "devuelto" si el RPC realmente funciono.
        _rpcAjustarSaldo(authSession.id, p.precio).then(function(saldoNuevo){
          var sn = Number(saldoNuevo)||0;
          authSession.saldo = sn;
          _refreshSaldoUI(sn);
          if(typeof saveSession==='function') saveSession(authSession);
          if(typeof sbAddMovimiento==='function') sbAddMovimiento(authSession.id, 'credito', p.precio, 'Devolucion Pedido #'+ord+' - producto no disponible');
          if(_movCompraId) _cancelarMovPorId(_movCompraId); else { _cancelarPendiente = true; _cancelarMovimientoCompra(authSession.id, ord); }

          registrarPedido(p.nombre+' (AUTO - NO DISPONIBLE, devuelto)', p.diamantes, 'diamantes', ffId, 0, 0, {estado:'rechazado', ord:ord});
          if(typeof sb!=='undefined' && sb.rpc && authSession && authSession.id){
            csAnularVentaDiamantes(authSession.id, ord); sb.rpc('revertir_puntos_pedido', { p_user_id: authSession.id, p_pedido_id: ord, p_motivo: 'Producto no disponible - devuelto' }).catch(function(){});
          }
          if(typeof tgNotifyPurchase==='function') tgNotifyPurchase(authSession.username, '\u26A0\uFE0F NO DISPONIBLE - Recarga AUTO\n\uD83D\uDCA0 Paquete: '+p.nombre+'\n\uD83C\uDFAE ID: '+ffId+'\n\u2757 '+errTxt+'\n\u2705 SALDO DEVUELTO automaticamente ('+fmt(p.precio)+')', p.precio, ord);
        }).catch(function(e){
          console.error('[RECARGA] devolucion fallo:', e);
          registrarPedido(p.nombre+' (NO DISPONIBLE - DEVOLUCION FALLIDA, REVISAR)', p.diamantes, 'diamantes', ffId, p.precio, 0, {ord:ord});
          if(typeof tgNotifyPurchase==='function') tgNotifyPurchase(authSession.username, '\uD83D\uDD25 <b>URGENTE: DEVOLUCION FALLIDA</b>\n\uD83D\uDCA0 Paquete: '+p.nombre+'\n\uD83C\uDFAE ID: '+ffId+'\n\u2757 Producto no disponible: '+errTxt+'\n\u274C La devolucion automatica de '+fmt(p.precio)+' AL CLIENTE FALLO ('+String((e&&e.message)||e)+')\n\n\uD83D\uDEA8 <b>DEVUELVE MANUALMENTE AL CLIENTE</b>', p.precio, ord);
        });
        if(btn){ btn.disabled=false; btn.className='ddet-btn on'; btn.innerHTML='Recargar con saldo &#8594;'; }
        if(msg){ msg.className='ddet-msg'; msg.innerHTML = _rcEstadoHTML('err', 'NO DISPONIBLE', 'Este paquete no esta disponible para tu ID en este momento. <b style="color:#fff">Tu saldo fue devuelto.</b> Intenta de nuevo o contacta al admin.'); }
        showToast('\u274C No disponible. Saldo devuelto.', 4000);
        _comprandoDiam = false;
      } else {
        // Error ambiguo: la recarga pudo haberse hecho igual. NO reembolsar, verificar manual.
        registrarPedido(p.nombre+' (AUTO - VERIFICAR)', p.diamantes, 'diamantes', ffId, p.precio, 0, {ord:ord});
        if(typeof tgNotifyPurchase==='function') tgNotifyPurchase(authSession.username, '\u26A0\uFE0F VERIFICAR - Recarga AUTO\n\uD83D\uDCA0 Paquete: '+p.nombre+'\n\uD83C\uDFAE ID: '+ffId+'\n\u2757 '+errTxt, p.precio, ord);
        if(btn){ btn.disabled=false; btn.className='ddet-btn on'; btn.innerHTML='Recargar con saldo &#8594;'; }
        if(msg){ msg.className='ddet-msg'; msg.innerHTML = _rcEstadoHTML('pending', '\u23F3 EN VERIFICACION', 'Tu recarga se esta verificando. Si no llega en unos minutos, contacta al admin con tu ID.'); }
        console.error('[RECARGA] Sin confirmar (no reembolsado):', JSON.stringify(res));
        _comprandoDiam = false;
        setTimeout(cerrarDiamDetalle, 4000);
      }
    }
  }).catch(function(err){
    // NO reembolsar: la recarga pudo haberse completado aunque la respuesta fallo
    registrarPedido(p.nombre+' (AUTO - VERIFICAR)', p.diamantes, 'diamantes', ffId, p.precio, 0, {ord:ord});
    if(typeof tgNotifyPurchase==='function') tgNotifyPurchase(authSession.username, '\u26A0\uFE0F VERIFICAR (sin respuesta) - Recarga AUTO\n\uD83D\uDCA0 Paquete: '+p.nombre+'\n\uD83C\uDFAE ID: '+ffId, p.precio, ord);
    if(btn){ btn.disabled=false; btn.className='ddet-btn on'; btn.innerHTML='Recargar con saldo &#8594;'; }
    if(msg){ msg.className='ddet-msg'; msg.innerHTML = _rcEstadoHTML('pending', '\u23F3 EN VERIFICACION', 'Tu recarga se esta verificando. Si no llega, contacta al admin.'); }
    console.error('[RECARGA] catch compra (no reembolsado):', err);
    _comprandoDiam = false;
    setTimeout(cerrarDiamDetalle, 4000);
  });
}

// ═══ Cuando el proveedor NO pudo confirmar el ID: mostrar advertencia clara
// y checkbox de responsabilidad. El boton de continuar queda deshabilitado
// hasta marcar el checkbox. El ID que el usuario escribio NUNCA se modifica. ═══
