// ADMIN: generar la key de un revendedor aprobado
function admGenerarApiKey(){
  if(!authSession || authSession.role !== 'admin'){ showToast('Solo admin'); return; }
  var user = ((document.getElementById('adm-api-user')||{}).value||'').trim();
  if(!user){ showToast('Escribe el username'); return; }

  fetch(SB_URL + '/rest/v1/rpc/admin_generar_api_key', {
    method: 'POST',
    headers: { 'apikey': SB_KEY, 'Authorization': 'Bearer ' + SB_KEY, 'Content-Type': 'application/json' },
    body: JSON.stringify({ p_admin_id: authSession.id, p_username: user })
  }).then(function(r){ return r.json(); }).then(function(res){
    var caja = document.getElementById('adm-api-result');
    if(typeof res === 'string' && res.indexOf('cs_live_') === 0){
      if(caja){ caja.textContent = res; caja.style.display = 'block'; caja.style.color = '#25d366'; }
      showToast('\u2705 Key generada para ' + user + '. Copiala y mandasela por privado.', 4000);
    } else {
      if(caja){ caja.textContent = String(res); caja.style.display = 'block'; caja.style.color = '#ff6b6b'; }
      showToast('No se pudo: ' + String(res), 4000);
    }
  }).catch(function(e){ showToast('Error de conexion'); console.error('[APIKEY]', e); });
}

// ADMIN: revocar la key de un revendedor
function admRevocarApiKey(){
  if(!authSession || authSession.role !== 'admin'){ showToast('Solo admin'); return; }
  var user = ((document.getElementById('adm-api-user')||{}).value||'').trim();
  if(!user){ showToast('Escribe el username'); return; }
  if(!confirm('Revocar la API key de ' + user + '? Dejara de funcionar al instante.')) return;

  fetch(SB_URL + '/rest/v1/rpc/admin_revocar_api_key', {
    method: 'POST',
    headers: { 'apikey': SB_KEY, 'Authorization': 'Bearer ' + SB_KEY, 'Content-Type': 'application/json' },
    body: JSON.stringify({ p_admin_id: authSession.id, p_username: user })
  }).then(function(r){ return r.json(); }).then(function(res){
    var caja = document.getElementById('adm-api-result');
    if(caja){ caja.textContent = String(res); caja.style.display = 'block'; caja.style.color = String(res).indexOf('OK') === 0 ? '#25d366' : '#ff6b6b'; }
    showToast(String(res), 3500);
  }).catch(function(e){ showToast('Error de conexion'); console.error('[APIKEY]', e); });
}


// ═══════════ SHEET DE RECARGA (billetera) ═══════════
var _rcCur = 'MXN';
var _rcMetodo = null;

function abrirRecargaSheet(){
  _rcMetodo = null;
  var ov = document.getElementById('sheet-recarga');
  if(ov) ov.classList.add('show');
  rcSetCur(_rcCur);
  rcActualizar();
}
function cerrarRecargaSheet(){
  var ov = document.getElementById('sheet-recarga');
  if(ov) ov.classList.remove('show');
}
function abrirMetodoSheet(){
  var ov = document.getElementById('sheet-metodo');
  if(ov) ov.classList.add('show');
}
function cerrarMetodoSheet(){
  var ov = document.getElementById('sheet-metodo');
  if(ov) ov.classList.remove('show');
}

function rcSetCur(cur){
  _rcCur = cur;
  var bm = document.getElementById('rc-cur-mxn');
  var bu = document.getElementById('rc-cur-usd');
  if(bm) bm.className = 'rc-cur' + (cur==='MXN'?' sel':'');
  if(bu) bu.className = 'rc-cur' + (cur==='USD'?' sel':'');
  var tag = document.getElementById('rc-cur-tag');
  if(tag) tag.textContent = cur;
  var minTxt = document.getElementById('rc-min-txt');
  if(minTxt) minTxt.textContent = cur==='MXN' ? 'Minimo $200 MXN' : 'Minimo $11.80 USD';
  // Chips por moneda
  var chips = cur==='MXN' ? [50,100,200,500,1000] : [3,10,25,50,100];
  var cont = document.getElementById('rc-chips');
  if(cont){
    cont.innerHTML = chips.map(function(c){
      return '<button class="rc-chip" onclick="rcPonMonto('+c+')">$'+c+'</button>';
    }).join('');
  }
  rcActualizar();
}

function rcPonMonto(v){
  var inp = document.getElementById('rc-monto');
  if(inp) inp.value = v;
  rcActualizar();
}

function rcActualizar(){
  var btn = document.getElementById('rc-continuar');
  if(!btn) return;
  var listo = !!_rcMetodo; // Unico metodo (USDT) no exige monto aqui; los paquetes estan en su ventana
  btn.className = 'rc-continuar' + (listo?' on':'');
  btn.textContent = !_rcMetodo ? 'Selecciona metodo de pago' : 'Continuar';
}

function rcElegirMetodo(m){
  _rcMetodo = m;
  cerrarMetodoSheet();
  var txt = document.getElementById('rc-met-txt');
  var ico = document.getElementById('rc-met-ico');
  var nombres = { binance:'USDT (TRC-20)' };
  if(txt){ txt.textContent = nombres[m]||m; txt.className='txt sel'; }
  if(ico){
    ico.innerHTML = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#26a17b" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M8 9h8M12 9v6M9.5 14h5"/></svg>';
  }
  rcActualizar();
}

function rcContinuar(){
  if(!_rcMetodo){ abrirMetodoSheet(); return; }
  // Unico metodo disponible: USDT. Abre su ventana con los montos, tal cual.
  cerrarRecargaSheet();
  if(typeof openBinanceModal==='function') openBinanceModal();
}


// ═══════════ RECARGAR SALDO (nueva pagina) ═══════════
var _recMoneda = 'MXN';
var REC_MONTOS = { MXN:[200,300,500,1000,2500], USD:[11.80,18,30,60,150] };
var REC_MIN = { MXN:200, USD:11.80 };

function recSetMoneda(m){
  _recMoneda = m;
  var bM = document.getElementById('rec-cur-mxn');
  var bU = document.getElementById('rec-cur-usd');
  if(bM){ bM.classList.toggle('on', m==='MXN'); }
  if(bU){ bU.classList.toggle('on', m==='USD'); }
  var lbl = document.getElementById('rec-cur-label');
  if(lbl) lbl.textContent = m;
  var av = document.getElementById('rec-min-aviso');
  if(av) av.innerHTML = '<span style="color:#1b87f5">&#9432;</span> Minimo ' + (m==='MXN'?'$200 MXN':'$11.80 USD');
  var inp = document.getElementById('rec-monto');
  if(inp) inp.value = (m==='MXN') ? 200 : 11.80;
  _recPintarMontos();
}

function _recPintarMontos(){
  var cont = document.getElementById('rec-montos');
  if(!cont) return;
  var montos = REC_MONTOS[_recMoneda] || REC_MONTOS.MXN;
  cont.innerHTML = montos.map(function(m){
    var lbl = (m % 1 === 0) ? m.toLocaleString('es-MX') : m.toFixed(2);
    return '<button onclick="recSetMonto('+m+')" class="wl-quick">$'+lbl+'</button>';
  }).join('');
}

function recSetMonto(m){
  var inp = document.getElementById('rec-monto');
  if(inp) inp.value = m;
  var cont = document.getElementById('rec-montos');
  if(cont){
    var lbl = '$' + ((m % 1 === 0) ? m.toLocaleString('es-MX') : m.toFixed(2));
    cont.querySelectorAll('.wl-quick').forEach(function(b){ b.classList.toggle('on', b.textContent === lbl); });
  }
}

// Tipo de recarga (obligatorio): para que va a usar el saldo
var _recTipo = null;
var REC_TIPO_LABEL = { ilim:'Diamantes con Bono', pase:'Pase Booyah', otro:'Otro', '1vez':'Diamantes 1 vez por ID' };
function _recTipoLabel(){
  if(_recTipo === 'otro'){
    var t = document.getElementById('rec-otro-txt');
    var txt = (t && t.value ? t.value.trim() : '');
    return 'Otro: ' + (txt || '(sin especificar)');
  }
  return REC_TIPO_LABEL[_recTipo] || _recTipo;
}

function recSetTipo(tipo){
  _recTipo = tipo;
  [['ilim','rec-tipo-ilim'],['pase','rec-tipo-pase'],['otro','rec-tipo-otro'],['1vez','rec-tipo-1vez']].forEach(function(par){
    var el = document.getElementById(par[1]);
    if(!el) return;
    el.classList.toggle('on', par[0] === tipo);
  });
  var wrap = document.getElementById('rec-otro-wrap');
  if(wrap){
    wrap.style.display = (tipo === 'otro') ? 'block' : 'none';
    if(tipo === 'otro'){ var t = document.getElementById('rec-otro-txt'); if(t) setTimeout(function(){ t.focus(); }, 50); }
  }
  var err = document.getElementById('rec-tipo-err');
  if(err) err.style.display = 'none';
}

function recElegirMetodo(metodo){
  // El tipo es obligatorio
  if(!_recTipo){
    var errT = document.getElementById('rec-tipo-err');
    if(errT) errT.style.display = 'block';
    showToast('Selecciona para que es tu saldo');
    try { document.getElementById('rec-tipo-ilim').scrollIntoView({behavior:'smooth', block:'center'}); } catch(e){}
    return;
  }
  var inp = document.getElementById('rec-monto');
  var monto = parseFloat((inp&&inp.value)||'0') || 0;
  var min = REC_MIN[_recMoneda] || 50;
  if(monto < min){
    showToast('El minimo es ' + (_recMoneda==='MXN'?'$200 MXN':'$11.80 USD'));
    return;
  }
  // Convertir a MXN si el usuario eligio USD
  var montoMXN = (_recMoneda==='USD') ? Math.round(monto * USD_MXN) : monto;
  _recMontoElegido = montoMXN;

  if(metodo==='binance'){ if(typeof openBinanceModal==='function') openBinanceModal(montoMXN); }
}
var _recMontoElegido = 0;

function recLimpiarTipo(){
  ['rec-tipo-ilim','rec-tipo-pase','rec-tipo-otro','rec-tipo-1vez'].forEach(function(id){
    var el = document.getElementById(id);
    if(el) el.classList.remove('on');
  });
  var wrap = document.getElementById('rec-otro-wrap');
  if(wrap) wrap.style.display = 'none';
  var t = document.getElementById('rec-otro-txt');
  if(t) t.value = '';
  var err = document.getElementById('rec-tipo-err');
  if(err) err.style.display = 'none';
}


// Marca la compra de un pedido como CANCELADA para que no cuente en el ranking
// Cancelar un movimiento por su ID exacto (metodo confiable)
// Lo pasa a 'compra_cancelada' para que NINGUN ranking lo cuente.
function _cancelarMovPorId(movId){
  if(!movId || typeof sb === 'undefined' || !sb.patch) return;
  sb.patch('movimientos_saldo', { tipo: 'compra_cancelada' }, 'id=eq.' + movId)
    .then(function(){
      console.log('[RANKING] Movimiento ' + movId + ' cancelado (no cuenta en ranking)');
    })
    .catch(function(e){ console.warn('[RANKING] no se pudo cancelar por ID', e); });
}

function _cancelarMovimientoCompra(userId, ord){
  if(!userId || !ord || typeof sb === 'undefined' || !sb.patch) return;

  // El movimiento de compra se guarda de forma asincrona en addSpend,
  // asi que puede no existir aun cuando la recarga falla rapido.
  // Reintentamos con retraso hasta encontrarlo y cancelarlo.
  var intentos = 0;
  var maxIntentos = 15;        // mas intentos (antes 8)
  var yaCancelado = false;
  function intentarCancelar(){
    if(yaCancelado) return;
    intentos++;
    // Buscar el movimiento por el numero de pedido (ilike = sin importar mayusculas)
    sb.get('movimientos_saldo',
      'user_id=eq.' + encodeURIComponent(userId) + '&tipo=eq.compra&descripcion=ilike.*Pedido*23' + ord + '*&select=id,descripcion'
    ).then(function(rows){
      if(rows && rows.length){
        // Encontrado: marcar TODOS los que coincidan como cancelados
        sb.patch('movimientos_saldo',
          { tipo: 'compra_cancelada' },
          'user_id=eq.' + encodeURIComponent(userId) + '&tipo=eq.compra&descripcion=ilike.*Pedido*23' + ord + '*'
        ).then(function(){
          yaCancelado = true;
          console.log('[RANKING] Pedido #' + ord + ' cancelado (ya no cuenta en ranking)');
        }).catch(function(e){
          if(intentos < maxIntentos) setTimeout(intentarCancelar, 2000);
          else console.warn('[RANKING] patch fallo', e);
        });
      } else if(intentos < maxIntentos){
        setTimeout(intentarCancelar, 2000);
      } else {
        console.warn('[RANKING] no se encontro el movimiento del pedido #' + ord);
      }
    }).catch(function(e){
      if(intentos < maxIntentos) setTimeout(intentarCancelar, 2000);
      else console.warn('[RANKING]', e);
    });
  }
  setTimeout(intentarCancelar, 2000);
  // Ademas, un barrido final tardio por si todo lo anterior fallo
  setTimeout(function(){
    if(yaCancelado) return;
    sb.patch('movimientos_saldo',
      { tipo: 'compra_cancelada' },
      'user_id=eq.' + encodeURIComponent(userId) + '&tipo=eq.compra&descripcion=ilike.*Pedido*23' + ord + '*'
    ).then(function(){ console.log('[RANKING] barrido final pedido #'+ord); }).catch(function(){});
  }, 35000); // 35s despues, cuando el movimiento seguro ya existe
}


// ═══════════ RESUMEN DE RECARGAS POR PAQUETE (Mis compras) ═══════════
// Normaliza los paquetes: los que se registraron como +20% se cuentan
// como su equivalente del +10% (misma recarga, distinta etiqueta).
var PAQUETES_RESUMEN = [
  { base:5600, bono:560,  nombre:'5600 Diamantes + 560 bono',  totales:[6160, 6720] },
  { base:2180, bono:218,  nombre:'2180 Diamantes + 218 Bono',  totales:[2398, 2616] },
  { base:1060, bono:106,  nombre:'1060 Diamantes + 106 Bono',  totales:[1166, 1272] },
  { base:520,  bono:52,   nombre:'520 Diamantes + 52 Bono',    totales:[572, 624] },
  { base:310,  bono:31,   nombre:'310 Diamantes + 31 Bono',    totales:[341, 372] },
  { base:100,  bono:10,   nombre:'100 Diamantes + 10 Bono',    totales:[110, 120] },
  { base:11200,bono:1120, nombre:'11200 Diamantes + 1120 Bono',totales:[12320, 13440] }
];

// Devuelve el paquete al que pertenece una descripcion, o null
function _paqueteDeDescripcion(desc){
  if(!desc) return null;
  var d = String(desc);
  // Numeros que aparecen en la descripcion (sin comas ni puntos de miles)
  var nums = (d.replace(/[.,](?=\d{3}\b)/g, '').match(/\d+/g) || []).map(Number);
  for(var i=0;i<PAQUETES_RESUMEN.length;i++){
    var p = PAQUETES_RESUMEN[i];
    for(var j=0;j<p.totales.length;j++){
      if(nums.indexOf(p.totales[j]) >= 0) return p;
    }
    // Tambien reconoce por la base (ej: "100 Diamantes + 10 Bono")
    if(nums.indexOf(p.base) >= 0 && nums.indexOf(p.bono) >= 0) return p;
  }
  return null;
}

function renderResumenRecargas(){
  var lista = document.getElementById('mc-resumen-lista');
  var totalBox = document.getElementById('mc-resumen-total');
  if(!lista) return;

  if(!authSession || !authSession.id || typeof sbGetMovimientos !== 'function'){
    lista.innerHTML = '<div style="text-align:center;padding:1.5rem;color:#6b7280;font-size:.8rem">Inicia sesion para ver tu resumen</div>';
    if(totalBox) totalBox.style.display = 'none';
    return;
  }

  sbGetMovimientos(authSession.id).then(function(rows){
    if(!rows || !rows.length){
      lista.innerHTML = '<div style="text-align:center;padding:1.5rem;color:#6b7280;font-size:.8rem">Aun no tienes recargas</div>';
      if(totalBox) totalBox.style.display = 'none';
      return;
    }

    // Contar solo compras reales (las canceladas/reembolsadas no cuentan)
    var acum = {}, totalN = 0, totalMonto = 0;
    rows.forEach(function(m){
      if(m.tipo !== 'compra') return;
      var p = _paqueteDeDescripcion(m.descripcion);
      if(!p) return;
      if(!acum[p.nombre]) acum[p.nombre] = { nombre:p.nombre, n:0, monto:0, base:p.base };
      acum[p.nombre].n += 1;
      acum[p.nombre].monto += Number(m.monto) || 0;
      totalN += 1;
      totalMonto += Number(m.monto) || 0;
    });

    var arr = Object.keys(acum).map(function(k){ return acum[k]; });
    if(!arr.length){
      lista.innerHTML = '<div style="text-align:center;padding:1.5rem;color:#6b7280;font-size:.8rem">Aun no tienes recargas de diamantes</div>';
      if(totalBox) totalBox.style.display = 'none';
      return;
    }
    arr.sort(function(a,b){ return b.base - a.base; });

    lista.innerHTML = arr.map(function(x){
      return '<div style="background:rgba(255,255,255,.03);border-radius:13px;padding:.9rem 1rem">'
        + '<div style="font-size:.92rem;color:#fff;font-weight:500;line-height:1.35">'+x.nombre+'</div>'
        + '<div style="font-size:.82rem;color:#6b7280;margin-top:.25rem">'+x.n+' recarga'+(x.n!==1?'s':'')+' &middot; <b style="color:#25d366">'+fmt(x.monto)+'</b></div>'
        + '</div>';
    }).join('');

    if(totalBox){
      totalBox.style.display = 'flex';
      var n = document.getElementById('mc-res-n');
      if(n) n.textContent = totalN;
      var mo = document.getElementById('mc-res-monto');
      if(mo) mo.textContent = fmt(totalMonto);
    }
  }).catch(function(e){
    lista.innerHTML = '<div style="text-align:center;padding:1.5rem;color:#6b7280;font-size:.8rem">Error al cargar el resumen</div>';
    console.error('[RESUMEN]', e);
  });
}


// ═══════════ LIKES POR CODIGO (nuevo sistema) ═══════════
