function renderLikesPlanes(){
  var cont = document.getElementById('lk-planes');
  if(!cont) return;
  cont.innerHTML = LIKES_PLANES.map(function(p){
    return '<div style="display:flex;align-items:center;gap:.85rem;background:rgba(255,255,255,.022);border:1px solid rgba(255,255,255,.08);border-radius:14px;padding:.9rem 1rem">'
      + '<div style="width:42px;height:42px;flex-shrink:0;border-radius:11px;background:'+p.color+'1a;border:1px solid '+p.color+'44;display:flex;align-items:center;justify-content:center;font-size:1.2rem">'+p.icono+'</div>'
      + '<div style="flex:1;min-width:0"><div style="font-family:Saira,sans-serif;font-weight:800;font-size:1rem;color:'+p.color+';letter-spacing:.5px">'+p.nombre+'</div><div style="font-size:.74rem;color:#6b7280">'+p.ids+'</div></div>'
      + '<div style="text-align:right;flex-shrink:0"><div style="font-family:Barlow,sans-serif;font-weight:700;font-size:1.25rem;color:#fff;line-height:1">$'+p.precio+'</div><div style="font-size:.6rem;color:#6b7280;letter-spacing:.5px">MXN / MES</div></div>'
      + '<button onclick="comprarPlanLikesWA(\''+p.id+'\')" style="flex-shrink:0;width:38px;height:38px;border-radius:10px;background:rgba(37,211,102,.12);border:1px solid rgba(37,211,102,.35);color:#25d366;cursor:pointer;display:flex;align-items:center;justify-content:center"><svg width="18" height="18" viewBox="0 0 24 24" fill="#25d366"><path d="M12 2a10 10 0 0 0-8.6 15.1L2 22l5-1.4A10 10 0 1 0 12 2zm4.4 12.1c-.2-.1-1.4-.7-1.6-.8s-.4-.1-.6.1-.6.8-.8 1-.3.2-.6.1a6.6 6.6 0 0 1-3.2-2.8c-.2-.4.2-.4.6-1.2a.6.6 0 0 0 0-.6l-.8-1.9c-.2-.5-.4-.4-.6-.4h-.5a1 1 0 0 0-.7.3 2.9 2.9 0 0 0-.9 2.2 5.1 5.1 0 0 0 1 2.7 11.5 11.5 0 0 0 4.5 4 5 5 0 0 0 3 .7 2.6 2.6 0 0 0 1.7-1.2 2.1 2.1 0 0 0 .1-1.2z"/></svg></button>'
      + '</div>';
  }).join('');
}

function comprarPlanLikesWA(planId){
  var p = LIKES_PLANES.filter(function(x){ return x.id===planId; })[0];
  if(!p) return;
  var quien = authSession ? authSession.username : '';
  var msg = 'Hola! Quiero comprar el plan de likes:\n'
    + 'Plan: ' + p.nombre + ' (' + p.ids + ')\n'
    + 'Precio: $' + p.precio + ' MXN/mes\n'
    + (quien ? ('Mi usuario: ' + quien + '\n') : '')
    + 'Mi ID de Free Fire: ';
  window.open('https://wa.me/' + WA + '?text=' + encodeURIComponent(msg), '_blank');
}



// ═══════════ PANEL DE GESTION DE LIKES (datos en Supabase) ═══════════
var _lkPlan = null;   // plan activo del usuario
var _lkIds = [];      // IDs registrados

// Llamar la RPC de canje (reemplaza la version stub anterior)
function canjearCodigoLikes(){
  var inp = document.getElementById('lk-codigo');
  var btn = document.getElementById('lk-canjear-btn');
  var msg = document.getElementById('lk-canjear-msg');
  var codigo = ((inp||{}).value||'').trim().toUpperCase();

  function showMsg(texto, tipo){
    if(!msg) return;
    msg.style.display = 'block';
    if(tipo==='ok'){ msg.style.background='rgba(37,211,102,.1)'; msg.style.border='1px solid rgba(37,211,102,.3)'; msg.style.color='#25d366'; }
    else if(tipo==='err'){ msg.style.background='rgba(255,60,60,.1)'; msg.style.border='1px solid rgba(255,60,60,.3)'; msg.style.color='#ff6b6b'; }
    else { msg.style.background='rgba(27,135,245,.08)'; msg.style.border='1px solid rgba(27,135,245,.3)'; msg.style.color='#1b87f5'; }
    msg.innerHTML = texto;
  }

  if(!authSession){ showMsg('Inicia sesion para canjear tu codigo.', 'err'); setTimeout(showAuthModal, 800); return; }
  if(!codigo || codigo.length < 6){ showMsg('Ingresa un codigo valido (ej: BS-XXXX-XXXX).', 'err'); return; }

  if(btn){ btn.disabled = true; btn.textContent = 'Canjeando...'; }

  fetch(_SB_URL_RPC + '/rest/v1/rpc/canjear_codigo_likes', {
    method:'POST',
    headers:{ 'apikey': SB_KEY, 'Authorization': 'Bearer ' + SB_KEY, 'Content-Type': 'application/json' },
    body: JSON.stringify({ p_user_id: authSession.id, p_codigo: codigo })
  }).then(function(r){ return r.json(); }).then(function(res){
    if(btn){ btn.disabled = false; btn.textContent = 'Canjear'; }
    if(res && res.success){
      var nom = _lkNombrePlan(res.plan);
      showMsg('\u2705 <b>Codigo activado!</b><br/>Tu plan <b>'+nom+'</b> ya esta activo. Actualizando...', 'ok');
      if(inp) inp.value = '';
      // Ocultar los planes de venta al instante (ya tiene plan)
      var secP = document.getElementById('lk-planes-seccion');
      if(secP) secP.style.display = 'none';
      var sinP = document.getElementById('lk-sin-plan');
      if(sinP) sinP.style.display = 'none';
      // Cargar el panel varias veces por si la DB tarda en reflejar el plan
      cargarPanelLikes();
      setTimeout(cargarPanelLikes, 700);
      setTimeout(cargarPanelLikes, 1800);
      setTimeout(function(){
        var pan = document.getElementById('lk-panel');
        if(pan) pan.scrollIntoView({behavior:'smooth', block:'start'});
      }, 900);
    } else {
      showMsg('\u274C ' + ((res && res.error) || 'Codigo invalido o ya usado.'), 'err');
    }
  }).catch(function(e){
    if(btn){ btn.disabled = false; btn.textContent = 'Canjear'; }
    showMsg('Error de conexion. Intenta de nuevo o escribenos por WhatsApp.', 'err');
    console.error('[CANJE]', e);
  });
}

function _lkNombrePlan(id){
  var p = LIKES_PLANES.filter(function(x){ return x.id===id; })[0];
  return p ? p.nombre : (id||'').toUpperCase();
}

// Cargar plan + IDs + envios y pintar el panel
function cargarPanelLikes(){
  var panel = document.getElementById('lk-panel');
  var sinPlan = document.getElementById('lk-sin-plan');
  if(!authSession){
    if(panel) panel.style.display = 'none';
    if(sinPlan) sinPlan.style.display = 'block';
    return;
  }

  sb.get('likes_planes_activos', 'user_id=eq.' + encodeURIComponent(authSession.id) + '&limit=1')
    .then(function(rows){
      var plan = (rows && rows[0]) || null;
      // Verificar que no este vencido
      if(plan && plan.vence_en && new Date(plan.vence_en) < new Date()) plan = null;
      _lkPlan = plan;

      if(!plan){
        if(panel) panel.style.display = 'none';
        if(sinPlan) sinPlan.style.display = 'block';
        var secP = document.getElementById('lk-planes-seccion');
        if(secP) secP.style.display = 'block';
        return;
      }
      if(panel) panel.style.display = 'block';
      if(sinPlan) sinPlan.style.display = 'none';
      var secPlanes = document.getElementById('lk-planes-seccion');
      if(secPlanes) secPlanes.style.display = 'none'; // con plan activo, ocultar la venta
      _pintarEstadoPlan(plan);
      cargarIdsLikes();
      cargarEnviosLikes();
      _lkInitVerif();
    }).catch(function(e){
      console.error('[LIKES] plan', e);
      if(panel) panel.style.display = 'none';
      if(sinPlan) sinPlan.style.display = 'block';
    });
}

function _pintarEstadoPlan(plan){
  var nom = _lkNombrePlan(plan.plan);
  var el;
  if(el=document.getElementById('lk-plan-nombre')) el.textContent = 'Plan ' + nom;
  var vence = plan.vence_en ? new Date(plan.vence_en).toLocaleDateString('es-MX',{day:'2-digit',month:'short'}) : '';
  if(el=document.getElementById('lk-plan-sub')) el.textContent = plan.plan==='ilimitado' ? ('Ilimitado \u00b7 vence '+vence) : ('Activo \u00b7 vence '+vence);
  if(el=document.getElementById('lk-plan-badge')){
    el.textContent = 'ACTIVO';
    el.style.background='rgba(37,211,102,.12)'; el.style.borderColor='rgba(37,211,102,.4)'; el.style.color='#25d366';
  }

  // Etiquetas con el nombre del plan
  var etiqueta = '\u00b7 ' + nom;
  if(el=document.getElementById('lk-lbl-envios')) el.textContent = etiqueta;
  if(el=document.getElementById('lk-lbl-ids'))    el.textContent = etiqueta;
  if(el=document.getElementById('lk-lbl-dias'))   el.textContent = etiqueta;

  // Dias restantes del plan
  if(plan.vence_en){
    var msDia = 24*60*60*1000;
    var diasRest = Math.max(0, Math.ceil((new Date(plan.vence_en) - new Date()) / msDia));
    if(el=document.getElementById('lk-dias-txt')) el.textContent = diasRest + (diasRest===1?' dia':' dias');
    if(el=document.getElementById('lk-dias-bar')) el.style.width = Math.min(100, diasRest/30*100) + '%';
  }

  // Reiniciar contador si cambio el dia
  var hoy = new Date().toISOString().slice(0,10);
  var envHoy = (plan.envios_fecha === hoy) ? (plan.envios_hoy||0) : 0;
  var envMax = plan.envios_dia||0;
  if(el=document.getElementById('lk-envios-txt')) el.textContent = envHoy+'/'+envMax;
  if(el=document.getElementById('lk-envios-bar')) el.style.width = (envMax? Math.min(100,envHoy/envMax*100):0)+'%';
  var disponibles = Math.max(0, envMax-envHoy);
  if(el=document.getElementById('lk-disp')) el.textContent = disponibles;
  if(el=document.getElementById('lk-manual-disp')) el.textContent = disponibles;
  if(el=document.getElementById('lk-total')) el.textContent = (plan.total_enviados||0).toLocaleString('es-MX');
}

// IDs registrados
function cargarIdsLikes(){
  if(!authSession) return;
  sb.get('likes_ids', 'user_id=eq.' + encodeURIComponent(authSession.id) + '&order=creado_en.desc')
    .then(function(rows){
      _lkIds = rows || [];
      _pintarIdsLikes();
    }).catch(function(e){ console.error('[LIKES] ids', e); });
}

function _pintarIdsLikes(){
  var cont = document.getElementById('lk-ids-lista');
  var maxIds = _lkPlan ? (_lkPlan.max_ids||0) : 0;
  var el;
  if(el=document.getElementById('lk-ids-txt')) el.textContent = _lkIds.length+'/'+maxIds+' IDs';
  if(el=document.getElementById('lk-ids-bar')) el.style.width = (maxIds? Math.min(100,_lkIds.length/maxIds*100):0)+'%';

  var addBtn = document.getElementById('lk-add-btn');
  if(addBtn){
    var lleno = _lkIds.length >= maxIds;
    addBtn.style.opacity = lleno ? '.4' : '1';
    addBtn.style.cursor = lleno ? 'not-allowed' : 'pointer';
  }

  if(!cont) return;
  if(!_lkIds.length){
    cont.innerHTML = '<div style="border:1px dashed rgba(255,255,255,.12);border-radius:14px;padding:2rem 1rem;text-align:center">'
      + '<svg width="30" height="30" viewBox="0 0 24 24" fill="none" stroke="#ffb84d" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" style="margin-bottom:.5rem"><path d="M13 2 3 14h7l-1 8 10-12h-7l1-8z"/></svg>'
      + '<div style="font-family:Barlow;font-weight:600;color:#9aa3b0;font-size:.9rem">Sin IDs registrados</div>'
      + '<div style="font-size:.76rem;color:#6b7280;margin-top:.2rem">Toca "Agregar ID" para comenzar</div></div>';
    return;
  }
  cont.innerHTML = _lkIds.map(function(x){
    var ult = x.ultimo_envio ? new Date(x.ultimo_envio).toLocaleDateString('es-MX',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}) : 'Aun sin envios';
    return '<div style="display:flex;align-items:center;gap:.8rem;background:rgba(255,255,255,.03);border-radius:12px;padding:.8rem .9rem;margin-bottom:.5rem">'
      + '<div style="width:38px;height:38px;flex-shrink:0;border-radius:10px;background:rgba(37,211,102,.1);display:flex;align-items:center;justify-content:center"><svg width="18" height="18" viewBox="0 0 24 24" fill="#25d366"><path d="M12 21s-7-4.5-9.5-9C1 9 2.5 5.5 6 5.5c2 0 3.2 1.2 4 2.3.8-1.1 2-2.3 4-2.3 3.5 0 5 3.5 3.5 6.5C19 16.5 12 21 12 21z"/></svg></div>'
      + '<div style="flex:1;min-width:0"><div style="font-family:Saira;font-weight:700;color:#fff;font-size:.92rem">'+(x.ff_nombre||'ID '+x.ff_id)+'</div><div style="font-size:.7rem;color:#6b7280">ID '+x.ff_id+' \u00b7 '+ult+'</div></div>'
      + '<button onclick="quitarIdLikes('+x.id+')" style="flex-shrink:0;width:32px;height:32px;border-radius:9px;background:rgba(255,60,60,.08);border:1px solid rgba(255,60,60,.22);color:#ff6b6b;cursor:pointer;font-size:1rem">\u00d7</button>'
      + '</div>';
  }).join('');
}

function agregarIdLikes(){
  if(!authSession){ showToast('Inicia sesion'); return; }
  if(!_lkPlan){ showToast('Necesitas un plan activo'); return; }
  if(_lkIds.length >= (_lkPlan.max_ids||0)){ showToast('Alcanzaste el limite de IDs de tu plan ('+_lkPlan.max_ids+')'); return; }

  var ffId = prompt('ID de Free Fire:');
  if(!ffId) return;
  ffId = String(ffId).replace(/\s/g,'').replace(/[^0-9]/g,'');
  if(ffId.length < 5){ showToast('ID invalido'); return; }

  showToast('\u23F3 Buscando jugador...');

  // Detectar el nombre del jugador automaticamente antes de guardar
  fetch(LIKES_ENVIAR_URL, {
    method:'POST',
    headers:{'Content-Type':'application/json'},
    body: JSON.stringify({ action:'verificar', uid: ffId })
  }).then(function(r){ return r.json(); }).then(function(res){
    var nombre = (res && res.valido && res.nombre) ? res.nombre : '';
    if(!res || !res.valido){
      showToast('\u26A0\uFE0F No encontramos ese jugador, revisa el ID');
      return;
    }
    sb.post('likes_ids', { user_id: authSession.id, ff_id: ffId, ff_nombre: nombre })
      .then(function(){ showToast('\u2705 ' + nombre + ' agregado'); cargarIdsLikes(); })
      .catch(function(e){
        if(String(e).indexOf('duplicate')>=0 || String(e).indexOf('unique')>=0) showToast('Ese ID ya esta registrado');
        else showToast('No se pudo agregar el ID');
        console.error('[LIKES] add', e);
      });
  }).catch(function(e){
    // Si falla la verificacion, guardar igual sin nombre
    sb.post('likes_ids', { user_id: authSession.id, ff_id: ffId, ff_nombre: '' })
      .then(function(){ showToast('\u2705 ID agregado'); cargarIdsLikes(); })
      .catch(function(){ showToast('No se pudo agregar el ID'); });
  });
}

function quitarIdLikes(rowId){
  if(!confirm('Quitar este ID de la lista?')) return;
  sb.del('likes_ids', 'id=eq.'+rowId)
    .then(function(){ showToast('ID eliminado'); cargarIdsLikes(); })
    .catch(function(e){ showToast('No se pudo quitar'); console.error('[LIKES] del', e); });
}

// Ultimos envios automaticos
function cargarEnviosLikes(){
  if(!authSession) return;
  sb.get('likes_envios', 'user_id=eq.' + encodeURIComponent(authSession.id) + '&order=enviado_en.desc&limit=10')
    .then(function(rows){
      var cont = document.getElementById('lk-envios-lista');
      if(!cont) return;
      if(!rows || !rows.length){
        cont.innerHTML = '<div style="text-align:center;padding:1.5rem;color:#6b7280;font-size:.8rem">Aun no hay envios registrados</div>';
        return;
      }
      cont.innerHTML = rows.map(function(x){
        var cuando = x.enviado_en ? new Date(x.enviado_en).toLocaleDateString('es-MX',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}) : '';
        var ok = (x.estado||'ok')==='ok';
        return '<div style="display:flex;align-items:center;gap:.7rem;padding:.6rem 0;border-bottom:1px solid rgba(255,255,255,.05)">'
          + '<div style="width:8px;height:8px;border-radius:50%;background:'+(ok?'#25d366':'#ff6b6b')+';flex-shrink:0"></div>'
          + '<div style="flex:1;min-width:0"><div style="font-size:.82rem;color:#fff">ID '+x.ff_id+'</div><div style="font-size:.68rem;color:#6b7280">'+cuando+'</div></div>'
          + '<div style="font-size:.78rem;color:'+(ok?'#25d366':'#ff6b6b')+';font-weight:600">'+(ok?('+'+(x.cantidad||0)):'Error')+'</div>'
          + '</div>';
      }).join('');
    }).catch(function(e){ console.error('[LIKES] envios', e); });
}


// ADMIN: generar codigo de likes desde el panel
function admGenerarCodigoLikes(){
  if(!authSession || authSession.role !== 'admin'){ showToast('Solo admin'); return; }
  var plan = ((document.getElementById('adm-lk-plan')||{}).value||'');
  var caja = document.getElementById('adm-lk-result');

  fetch(_SB_URL_RPC + '/rest/v1/rpc/admin_generar_codigo_likes', {
    method:'POST',
    headers:{ 'apikey': SB_KEY, 'Authorization':'Bearer '+SB_KEY, 'Content-Type':'application/json' },
    body: JSON.stringify({ p_admin_id: authSession.id, p_plan: plan })
  }).then(function(r){ return r.json(); }).then(function(res){
    if(typeof res === 'string' && res.indexOf('CS-') === 0){
      if(caja){ caja.textContent = res; caja.style.display = 'block'; caja.style.color = '#25d366'; }
      showToast('\u2705 Codigo generado. Copialo y mandaselo al cliente.', 4000);
    } else {
      if(caja){ caja.textContent = String(res); caja.style.display = 'block'; caja.style.color = '#ff6b6b'; }
      showToast('No se pudo: ' + String(res), 4000);
    }
  }).catch(function(e){ showToast('Error de conexion'); console.error('[LIKES-GEN]', e); });
}


// ═══════════ ENVIAR LIKES MANUAL (via Free Fire Services) ═══════════
var LIKES_ENVIAR_URL = 'https://pnotsqsudqpwqzssevig.supabase.co/functions/v1/likes-sender-';

function enviarLikesManual(){
  var inp = document.getElementById('lk-manual-uid');
  var btn = document.getElementById('lk-manual-btn');
  var msg = document.getElementById('lk-manual-msg');
  var regionSel = document.getElementById('lk-manual-region');
  var uid = ((inp||{}).value||'').trim();
  var region = (regionSel && regionSel.value) || 'SAC';

  function showMsg(texto, tipo){
    if(!msg) return;
    msg.style.display = 'block';
    if(tipo==='ok'){ msg.style.background='rgba(37,211,102,.1)'; msg.style.border='1px solid rgba(37,211,102,.3)'; msg.style.color='#25d366'; }
    else if(tipo==='err'){ msg.style.background='rgba(255,60,60,.1)'; msg.style.border='1px solid rgba(255,60,60,.3)'; msg.style.color='#ff6b6b'; }
    else { msg.style.background='rgba(27,135,245,.08)'; msg.style.border='1px solid rgba(27,135,245,.3)'; msg.style.color='#1b87f5'; }
    msg.innerHTML = texto;
  }

  if(!authSession){ showMsg('Inicia sesion.', 'err'); return; }
  if(!_lkPlan){ showMsg('Necesitas un plan activo.', 'err'); return; }
  if(!uid || uid.replace(/\D/g,'').length < 5){ showMsg('Ingresa un UID valido.', 'err'); return; }

  // Verificar cupo diario local (la funcion tambien lo valida en el servidor)
  var hoy = new Date().toISOString().slice(0,10);
  var envHoy = (_lkPlan.envios_fecha === hoy) ? (_lkPlan.envios_hoy||0) : 0;
  var disponibles = Math.max(0, (_lkPlan.envios_dia||0) - envHoy);
  if(disponibles <= 0){ showMsg('Ya usaste todos tus envios de hoy. Vuelve manana.', 'err'); return; }

  if(btn){ btn.disabled = true; btn.style.opacity = '.5'; }
  showMsg('\u23F3 Enviando likes...', 'info');

  fetch(LIKES_ENVIAR_URL, {
    method:'POST',
    headers:{'Content-Type':'application/json'},
    body: JSON.stringify({ action:'enviar', uid: uid, region: region, user_id: authSession.id })
  }).then(function(r){ return r.json(); }).then(function(res){
    if(btn){ btn.disabled = false; btn.style.opacity = '1'; }
    if(res && res.success){
      if(msg) msg.style.display = 'none';
      var pf = document.getElementById('lk-manual-perfil');
      if(pf) pf.style.display = 'none';
      var card = document.getElementById('lk-manual-resultado');
      if(card){
        var inicial = ((res.nombre||'?').charAt(0)||'?').toUpperCase();
        card.style.display = 'block';
        card.innerHTML =
          '<div style="background:rgba(37,211,102,.06);border:1px solid rgba(37,211,102,.3);border-radius:15px;padding:1.1rem 1rem">'
          + '<div style="display:flex;align-items:center;gap:.85rem;margin-bottom:1rem">'
          +   '<div style="width:46px;height:46px;flex-shrink:0;border-radius:12px;background:linear-gradient(135deg,#128c3e,#25d366);display:flex;align-items:center;justify-content:center;font-family:Saira;font-weight:800;font-size:1.3rem;color:#fff">'+inicial+'</div>'
          +   '<div style="flex:1;min-width:0">'
          +     '<div style="font-family:Barlow,sans-serif;font-weight:700;font-size:1rem;color:#fff;word-break:break-word">'+(res.nombre||'Jugador')+'</div>'
          +     '<div style="font-size:.72rem;color:#6b7280">UID '+uid+' \u00b7 '+(res.region||region)+'</div>'
          +   '</div>'
          +   '<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#25d366" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="m8.5 12 2.5 2.5 4.5-5"/></svg>'
          + '</div>'
          + '<div style="display:flex;align-items:center;gap:.5rem">'
          +   '<div style="flex:1;text-align:center;background:rgba(255,255,255,.03);border-radius:11px;padding:.7rem"><div style="font-size:.62rem;color:#6b7280;letter-spacing:.5px;margin-bottom:.15rem">ANTES</div><div style="font-family:Saira;font-weight:800;font-size:1.15rem;color:#9aa3b0">'+(res.antes||'-')+'</div></div>'
          +   '<div style="flex-shrink:0;display:flex;flex-direction:column;align-items:center"><span style="font-size:.7rem;color:#25d366;font-weight:700">+'+res.enviadas+'</span><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#25d366" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12h14M13 6l6 6-6 6"/></svg></div>'
          +   '<div style="flex:1;text-align:center;background:rgba(37,211,102,.08);border:1px solid rgba(37,211,102,.25);border-radius:11px;padding:.7rem"><div style="font-size:.62rem;color:#25d366;letter-spacing:.5px;margin-bottom:.15rem">DESPUES</div><div style="font-family:Saira;font-weight:800;font-size:1.15rem;color:#25d366">'+(res.despues||'-')+'</div></div>'
          + '</div>'
          + '<div style="text-align:center;margin-top:.85rem;font-size:.78rem;color:#25d366;font-weight:600">\u2764\uFE0F '+res.enviadas+' likes enviados con exito</div>'
          + '<div style="display:flex;gap:.6rem;margin-top:1rem">'
          +   '<button onclick="descargarImagenLikes()" style="flex:1;padding:.7rem;background:rgba(37,211,102,.12);border:1px solid rgba(37,211,102,.35);color:#25d366;border-radius:11px;font-family:Barlow,sans-serif;font-weight:700;font-size:.78rem;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:.4rem"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4M7 10l5 5 5-5M12 15V3"/></svg>Descargar</button>'
          +   '<button onclick="compartirImagenLikes()" style="flex:1;padding:.7rem;background:rgba(27,135,245,.12);border:1px solid rgba(27,135,245,.35);color:#1b87f5;border-radius:11px;font-family:Barlow,sans-serif;font-weight:700;font-size:.78rem;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:.4rem"><svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="M8.6 13.5l6.8 4M15.4 6.5l-6.8 4"/></svg>Compartir</button>'
          + '</div>'
          + '</div>';
        // Guardar datos para generar la imagen
        _lkUltimoResultado = { nombre: (res.nombre||'Jugador'), uid: uid, region: (res.region||region), antes: (res.antes||'-'), despues: (res.despues||'-'), enviadas: res.enviadas };
      }
      if(inp) inp.value = '';
      setTimeout(function(){ cargarPanelLikes(); }, 1000);
    } else {
      var card2 = document.getElementById('lk-manual-resultado');
      if(card2) card2.style.display = 'none';
      showMsg('\u274C ' + ((res && res.error) || 'No se pudieron enviar los likes.'), 'err');
    }
  }).catch(function(e){
    if(btn){ btn.disabled = false; btn.style.opacity = '1'; }
    showMsg('Error de conexion. Intenta de nuevo.', 'err');
    console.error('[LIKES-ENVIAR]', e);
  });
}


// ═══════════ VERIFICAR PERFIL AL ESCRIBIR UID ═══════════
var _lkVerifTimer = null;
var _lkPerfilOk = false;

function _lkInitVerif(){
  var inp = document.getElementById('lk-manual-uid');
  if(!inp || inp._verifHooked) return;
  inp._verifHooked = true;
  inp.addEventListener('input', function(){
    _lkPerfilOk = false;
    var perfil = document.getElementById('lk-manual-perfil');
    if(perfil) perfil.style.display = 'none';
    clearTimeout(_lkVerifTimer);
    var uid = (inp.value||'').trim();
    var perfil2 = document.getElementById('lk-manual-perfil');
    if(uid.replace(/\D/g,'').length < 5){ if(perfil2) perfil2.style.display='none'; return; }
    _lkVerifTimer = setTimeout(function(){ _lkVerificarPerfil(uid); }, 700);
  });
}

function _lkVerificarPerfil(uid){
  var perfil = document.getElementById('lk-manual-perfil');
  if(!perfil) return;
  perfil.style.display = 'block';
  perfil.innerHTML = '<div style="display:flex;align-items:center;gap:.5rem;font-size:.78rem;color:#7cc0ff;background:rgba(27,135,245,.05);border:1px solid rgba(27,135,245,.2);border-radius:12px;padding:.7rem .9rem"><span style="display:inline-block;width:14px;height:14px;border:2px solid rgba(124,192,255,.3);border-top-color:#7cc0ff;border-radius:50%;animation:lkspin .7s linear infinite"></span>Buscando jugador...</div>';

  fetch(LIKES_ENVIAR_URL, {
    method:'POST',
    headers:{'Content-Type':'application/json'},
    body: JSON.stringify({ action:'verificar', uid: uid })
  }).then(function(r){ return r.json(); }).then(function(res){
    if(res && res.success && res.valido){
      _lkPerfilOk = true;
      // Guardar la region detectada en el campo oculto
      var regEl = document.getElementById('lk-manual-region');
      if(regEl) regEl.value = res.region || 'AUTO';
      var ini = ((res.nombre||'?').charAt(0)||'?').toUpperCase();
      perfil.innerHTML =
        '<div style="display:flex;align-items:center;gap:.8rem;background:linear-gradient(135deg,rgba(37,211,102,.1),rgba(27,135,245,.04));border:1px solid rgba(37,211,102,.3);border-radius:14px;padding:.85rem .95rem">'
        + '<div style="width:44px;height:44px;flex-shrink:0;border-radius:12px;background:linear-gradient(135deg,#0a4fa8,#1b87f5);display:flex;align-items:center;justify-content:center;font-family:Saira;font-weight:800;font-size:1.3rem;color:#fff;box-shadow:0 3px 12px rgba(27,135,245,.3)">'+ini+'</div>'
        + '<div style="flex:1;min-width:0">'
        +   '<div style="font-family:Barlow,sans-serif;font-weight:700;font-size:1rem;color:#fff;word-break:break-word">'+(res.nombre||'Jugador')+'</div>'
        +   '<div style="display:flex;align-items:center;gap:.4rem;margin-top:.15rem"><span style="font-size:.65rem;color:#9aa3b0;border:1px solid rgba(255,255,255,.14);border-radius:6px;padding:.1rem .45rem;font-weight:600">'+(res.region||'?')+'</span>'+(res.nivel?('<span style="font-size:.7rem;color:#6b7280">Nivel '+res.nivel+'</span>'):'')+'</div>'
        + '</div>'
        + '<div style="flex-shrink:0;display:flex;flex-direction:column;align-items:center;gap:.15rem"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#25d366" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="m8.5 12 2.5 2.5 4.5-5"/></svg><span style="font-size:.58rem;color:#25d366;font-weight:700">LISTO</span></div>'
        + '</div>';
    } else {
      // Verificacion silenciosa: si no lo encuentra al escribir, solo ocultamos
      // el perfil (no molestamos con error rojo). El error real sale al ENVIAR.
      _lkPerfilOk = false;
      perfil.style.display = 'none';
    }
  }).catch(function(e){
    if(perfil) perfil.style.display = 'none';
    console.error('[LIKES-VERIF]', e);
  });
}


// ═══════════ TOP LIKES (clasificacion de envios) ═══════════
function renderTopLikes(){
  var cont = document.getElementById('toplikes-lista');
  if(!cont) return;
  cont.innerHTML = '<div style="text-align:center;padding:2rem;color:#6b7280;font-size:.85rem">Cargando...</div>';

  if(typeof sb === 'undefined' || !sb.get){
    cont.innerHTML = '<div style="text-align:center;padding:2rem;color:#6b7280;font-size:.85rem">No disponible</div>';
    return;
  }

  // Traer todos los envios y sumar por usuario
  sb.get('likes_envios', 'select=user_id,cantidad&estado=eq.ok&limit=5000')
    .then(function(rows){
      if(!rows || !rows.length){
        cont.innerHTML = '<div style="text-align:center;padding:2rem;color:#6b7280;font-size:.85rem">Aun no hay envios registrados</div>';
        return;
      }
      var acum = {};
      rows.forEach(function(r){
        if(!r.user_id) return;
        acum[r.user_id] = (acum[r.user_id]||0) + (Number(r.cantidad)||0);
      });
      var arr = Object.keys(acum).map(function(uid){ return { user_id:uid, total:acum[uid] }; });
      arr.sort(function(a,b){ return b.total - a.total; });
      arr = arr.slice(0, 15);

      // Obtener los usernames de esos user_id
      var ids = arr.map(function(x){ return x.user_id; });
      var q = 'select=id,username&id=in.(' + ids.join(',') + ')';
      sb.get('profiles', q).then(function(perfiles){
        var nombres = {};
        (perfiles||[]).forEach(function(p){ nombres[p.id] = p.username; });
        _pintarTopLikes(arr, nombres);
      }).catch(function(){
        _pintarTopLikes(arr, {});
      });
    }).catch(function(e){
      cont.innerHTML = '<div style="text-align:center;padding:2rem;color:#6b7280;font-size:.85rem">Error al cargar</div>';
      console.error('[TOPLIKES]', e);
    });
}

function _pintarTopLikes(arr, nombres){
  var cont = document.getElementById('toplikes-lista');
  if(!cont) return;
  var yo = authSession ? authSession.id : null;

  cont.innerHTML = arr.map(function(x, i){
    var pos = i + 1;
    var nombre = nombres[x.user_id] || 'Usuario';
    var esYo = (x.user_id === yo);
    // Medalla para los 3 primeros
    var medalla = '';
    if(pos === 1) medalla = '<svg width="20" height="20" viewBox="0 0 24 24" fill="#ffd700" style="flex-shrink:0"><path d="M13 2 L15.5 8 L22 8.5 L17 13 L18.5 20 L13 16.5 L7.5 20 L9 13 L4 8.5 L10.5 8 Z"/></svg>';
    else if(pos === 2) medalla = '<svg width="18" height="18" viewBox="0 0 24 24" fill="#c0c0c0" style="flex-shrink:0"><circle cx="12" cy="12" r="9"/></svg>';
    else if(pos === 3) medalla = '<svg width="18" height="18" viewBox="0 0 24 24" fill="#cd7f32" style="flex-shrink:0"><circle cx="12" cy="12" r="9"/></svg>';

    var borde = esYo ? 'rgba(37,211,102,.4)' : 'rgba(255,255,255,.06)';
    var fondo = esYo ? 'rgba(37,211,102,.05)' : 'rgba(255,255,255,.02)';

    return '<div style="display:flex;align-items:center;justify-content:space-between;gap:.8rem;background:'+fondo+';border:1px solid '+borde+';border-radius:14px;padding:1rem 1.05rem">'
      + '<div style="display:flex;align-items:center;gap:.7rem;min-width:0">'
      +   (medalla || '<span style="width:20px;flex-shrink:0"></span>')
      +   '<span style="font-family:Barlow,sans-serif;font-weight:600;font-size:1rem;color:#fff;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+pos+'. '+nombre+(esYo?' <span style=\'font-size:.62rem;color:#25d366\'>(tu)</span>':'')+'</span>'
      + '</div>'
      + '<div style="text-align:right;flex-shrink:0"><div style="font-family:Saira,sans-serif;font-weight:800;font-size:1.15rem;color:#25d366;line-height:1">'+x.total.toLocaleString('es-MX')+'</div><div style="font-size:.58rem;color:#6b7280;letter-spacing:.5px">LIKES ENVIADOS</div></div>'
      + '</div>';
  }).join('');
}


// ═══════════ GENERAR IMAGEN DEL RESULTADO DE LIKES ═══════════
var _lkUltimoResultado = null;

function _lkGenerarCanvas(callback){
  if(!_lkUltimoResultado){ return; }
  var r = _lkUltimoResultado;
  var W = 1080, H = 1080;
  var canvas = document.createElement('canvas');
  canvas.width = W; canvas.height = H;
  var ctx = canvas.getContext('2d');

  function texto(t, x, y, font, color, align){
    ctx.font = font; ctx.fillStyle = color; ctx.textAlign = align || 'center';
    ctx.fillText(t, x, y);
  }
  function glow(color, blur){ ctx.shadowColor = color; ctx.shadowBlur = blur; }
  function noGlow(){ ctx.shadowColor = 'transparent'; ctx.shadowBlur = 0; }

  function dibujar(logoImg){
    // ── Fondo negro ──
    ctx.fillStyle = '#050a0e';
    ctx.fillRect(0, 0, W, H);

    // ── Marco con brillo verde ──
    var marco = ctx.createLinearGradient(0, 0, W, H);
    marco.addColorStop(0, '#25d366');
    marco.addColorStop(1, '#1b87f5');
    ctx.strokeStyle = marco; ctx.lineWidth = 6;
    glow('#25d366', 22);
    _roundRect(ctx, 28, 28, W-56, H-56, 40); ctx.stroke();
    noGlow();

    // ═══ 1) LOGO (arriba, solo, centrado) ═══
    var y = 130;
    if(logoImg){
      var lw = 560, lh = lw * (logoImg.height/logoImg.width);
      // limitar altura del logo
      if(lh > 150){ lh = 150; lw = lh * (logoImg.width/logoImg.height); }
      ctx.drawImage(logoImg, (W-lw)/2, y - lh/2, lw, lh);
      y += lh/2 + 45;
    } else {
      glow('#1b87f5', 15);
      texto('CIBER', W/2 - 100, y, '900 88px Arial', '#fff', 'center');
      texto('STORE', W/2 + 145, y, '900 88px Arial', '#1b87f5', 'center');
      noGlow();
      y += 90;
    }

    // LIKES ENVIADOS
    y += 25;
    glow('#25d366', 18);
    texto('\u2764\uFE0F LIKES ENVIADOS', W/2, y, '900 72px Arial', '#25d366', 'center');
    noGlow();

    // Nombre
    y += 68;
    var nombreCorto = r.nombre.length > 16 ? r.nombre.slice(0,16) : r.nombre;
    texto(nombreCorto.toUpperCase(), W/2, y, '800 54px Arial', '#e8f0f0', 'center');

    // ═══ 4) Caja UID | region ═══
    y += 35;
    var cajaW = 780, cajaX = (W-cajaW)/2, cajaH = 105;
    ctx.fillStyle = 'rgba(37,211,102,.05)';
    ctx.strokeStyle = 'rgba(37,211,102,.4)'; ctx.lineWidth = 2;
    _roundRect(ctx, cajaX, y, cajaW, cajaH, 26); ctx.fill(); ctx.stroke();
    ctx.strokeStyle = 'rgba(255,255,255,.15)'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(W/2, y+28); ctx.lineTo(W/2, y+cajaH-28); ctx.stroke();
    texto('\ud83d\udc64  UID', cajaX + cajaW/4, y + 45, '700 28px Arial', '#25d366', 'center');
    texto(r.uid, cajaX + cajaW/4, y + 88, '800 42px Arial', '#fff', 'center');
    texto('\ud83d\udee1\ufe0f  ' + r.region, cajaX + cajaW*3/4, y + 72, '800 46px Arial', '#fff', 'center');

    // ═══ 5) Cajas ANTES / DESPUES ═══
    y += cajaH + 40;
    var boxW = 430, boxH = 255, gap = 50;
    var x1 = (W - boxW*2 - gap)/2, x2 = x1 + boxW + gap;

    ctx.fillStyle = 'rgba(255,255,255,.03)';
    ctx.strokeStyle = 'rgba(255,255,255,.12)'; ctx.lineWidth = 2;
    _roundRect(ctx, x1, y, boxW, boxH, 32); ctx.fill(); ctx.stroke();
    texto('ANTES', x1 + boxW/2, y + 70, '700 38px Arial', '#9aa3b0', 'center');
    texto(String(r.antes), x1 + boxW/2, y + 175, '900 84px Arial', '#c9d1e0', 'center');

    ctx.fillStyle = 'rgba(37,211,102,.08)';
    glow('#25d366', 18);
    _roundRect(ctx, x2, y, boxW, boxH, 32); ctx.fill();
    noGlow();
    ctx.strokeStyle = 'rgba(37,211,102,.5)'; ctx.lineWidth = 3;
    _roundRect(ctx, x2, y, boxW, boxH, 32); ctx.stroke();
    texto('DESPUES', x2 + boxW/2, y + 70, '700 38px Arial', '#25d366', 'center');
    glow('#25d366', 12);
    texto(String(r.despues), x2 + boxW/2, y + 175, '900 84px Arial', '#25d366', 'center');
    noGlow();

    // +N circulo (encima, en el centro entre las cajas)
    var cx = W/2, cy = y + boxH/2;
    ctx.fillStyle = '#050a0e';
    glow('#25d366', 18);
    ctx.beginPath(); ctx.arc(cx, cy, 72, 0, Math.PI*2); ctx.fill();
    noGlow();
    ctx.strokeStyle = '#25d366'; ctx.lineWidth = 4;
    ctx.beginPath(); ctx.arc(cx, cy, 72, 0, Math.PI*2); ctx.stroke();
    texto('+' + r.enviadas, cx, cy - 2, '900 52px Arial', '#25d366', 'center');
    texto('\u00bb\u00bb\u00bb', cx, cy + 38, '700 26px Arial', '#25d366', 'center');

    // ═══ 6) Barra web | WhatsApp ═══
    y += boxH + 40;
    var barH = 125;
    ctx.fillStyle = 'rgba(37,211,102,.06)';
    ctx.strokeStyle = 'rgba(37,211,102,.35)'; ctx.lineWidth = 2;
    _roundRect(ctx, 70, y, W-140, barH, 28); ctx.fill(); ctx.stroke();
    ctx.strokeStyle = 'rgba(255,255,255,.12)'; ctx.lineWidth = 1;
    ctx.beginPath(); ctx.moveTo(W/2, y+32); ctx.lineTo(W/2, y+barH-32); ctx.stroke();
    texto('\ud83c\udf10 ciberstore.lat', W/4 + 35, y + 62, '800 40px Arial', '#25d366', 'center');
    texto('Compra tu plan de likes', W/4 + 35, y + 100, '400 26px Arial', '#8a94a6', 'center');
    texto('\ud83d\udcf2 WHATSAPP', W*3/4 - 35, y + 58, '800 36px Arial', '#25d366', 'center');
    texto('+1 (289) 427-3983', W*3/4 - 35, y + 100, '800 38px Arial', '#fff', 'center');

    // ═══ 7) Slogan final (bien abajo, sin encimar) ═══
    texto('\ud83d\udee1\ufe0f  TU EXITO, NUESTRA MISION', W/2, H - 55, '800 30px Arial', '#1b87f5', 'center');

    callback(canvas);
  }

  var logo = new Image();
  logo.crossOrigin = 'anonymous';
  logo.onload = function(){ dibujar(logo); };
  logo.onerror = function(){ dibujar(null); };
  logo.src = 'img/logo-ciberstore.png';
}

function _roundRect(ctx, x, y, w, h, r){
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

function descargarImagenLikes(){
  _lkGenerarCanvas(function(canvas){
    try {
      var link = document.createElement('a');
      link.download = 'ciberstore-likes-' + Date.now() + '.png';
      link.href = canvas.toDataURL('image/png');
      link.click();
      showToast('\u2705 Imagen descargada');
    } catch(e){ showToast('No se pudo descargar'); console.error(e); }
  });
}

function compartirImagenLikes(){
  _lkGenerarCanvas(function(canvas){
    canvas.toBlob(function(blob){
      if(!blob){ showToast('No se pudo generar la imagen'); return; }
      var file = new File([blob], 'ciberstore-likes.png', { type:'image/png' });
      if(navigator.share && navigator.canShare && navigator.canShare({ files:[file] })){
        navigator.share({
          files: [file],
          title: 'Mis likes en CiberStore',
          text: 'Consegui likes en ciberstore.lat \ud83d\udd25'
        }).catch(function(){});
      } else {
        // Fallback: descargar
        var link = document.createElement('a');
        link.download = 'ciberstore-likes.png';
        link.href = URL.createObjectURL(blob);
        link.click();
        showToast('Imagen lista para compartir');
      }
    }, 'image/png');
  });
}


// ═══════════ ARREGLO: PERMITIR PEGAR IDs ═══════════
// Algunos teclados numericos en Android rechazan el texto pegado.
// Este parche fuerza que todos los campos de ID acepten el pegado
// (limpiando espacios y caracteres raros, dejando solo lo necesario).
document.addEventListener('DOMContentLoaded', function(){
  // IDs de campos donde el cliente pega su ID de Free Fire / clan / UID
  var camposId = ['f1','f2','bundle-id','pase-id','lk-manual-uid','hcff-token',
                  'v1-id','ilim-id','bonus-id','lk200-id','lk2k-id','ff-id',
                  'clan-nombre','clan-id','m-clan-id',
                  'cart-ff-id','cart-ff-id2','ac80-id','frag-id','l2k-id','m-ff-id'];

  function limpiarId(txt){
    // Quitar espacios, saltos de linea y todo lo que no sea numero
    return String(txt||'').replace(/\s/g,'').replace(/[^0-9]/g,'');
  }

  function hookPaste(el){
    if(!el || el._pasteHooked) return;
    el._pasteHooked = true;
    el.addEventListener('paste', function(e){
      try {
        var pegado = (e.clipboardData || window.clipboardData).getData('text');
        if(pegado){
          // Decidir si limpiar a solo numeros: campos de ID/tel/numericos
          var esNumerico = (el.type === 'tel') || (el.inputMode === 'numeric') ||
                           (el.getAttribute && el.getAttribute('inputmode') === 'numeric') ||
                           (camposId.indexOf(el.id) >= 0);
          var limpio = esNumerico ? limpiarId(pegado) : pegado.trim();
          e.preventDefault();
          var ini = el.selectionStart || 0;
          var fin = el.selectionEnd || 0;
          var val = el.value || '';
          el.value = val.slice(0, ini) + limpio + val.slice(fin);
          el.dispatchEvent(new Event('input', { bubbles:true }));
        }
      } catch(err){ /* si falla, dejar el pegado normal */ }
    });
  }

  camposId.forEach(function(id){
    var el = document.getElementById(id);
    if(el) hookPaste(el);
  });

  // Tambien enganchar cualquier campo futuro con clase .finput cuando se abra un modal
  window._hookPasteAll = function(){
    // Enganchar TODOS los inputs de texto/tel/numerico de la app
    // para que dejen pegar IDs sin problema
    document.querySelectorAll('input[type="text"], input[type="tel"], input[inputmode="numeric"], input.finput').forEach(function(el){
      hookPaste(el);
    });
  };
  window._hookPasteAll();
});


// ═══════════ BIO LARGA (servicio con saldo + entrega link) ═══════════
var BIOLARGA_PRECIO = 25;
var BIOLARGA_LINK = 'https://hyperbioff.com/';
var _biolargaBusy = false;

function _refreshBioLargaSaldo(){
  var el = document.getElementById('biolarga-saldo');
  if(el) el.textContent = authSession ? ('$' + (authSession.saldo||0) + ' MXN') : '$0 MXN';
}

function comprarBioLarga(){
  if(!authSession){ showToast('Inicia sesion para comprar'); setTimeout(showAuthModal, 600); return; }
  if(_biolargaBusy){ return; }

  var saldo = authSession.saldo || 0;
  if(saldo < BIOLARGA_PRECIO){
    showToast('Saldo insuficiente. Necesitas $' + BIOLARGA_PRECIO + ' MXN', 3500);
    setTimeout(function(){ goPage('saldo'); }, 900);
    return;
  }

  if(!confirm('Comprar BIO LARGA por $' + BIOLARGA_PRECIO + ' MXN?\n\nSe descontara de tu saldo y recibiras el enlace.')) return;

  _biolargaBusy = true;
  var btn = document.getElementById('biolarga-btn');
  if(btn){ btn.disabled = true; btn.textContent = 'Procesando...'; btn.style.opacity = '.6'; }

  var ord = (typeof getNextOrder === 'function') ? getNextOrder() : Math.floor(Math.random()*9000+1000);

  // Descontar saldo (atomico)
  addSpend(BIOLARGA_PRECIO, 'BIO LARGA - Pedido #' + ord);

  // Notificar a Telegram
  if(typeof tgNotifyPurchase === 'function'){
    tgNotifyPurchase(authSession.username, 'BIO LARGA (5 usos/dia)', BIOLARGA_PRECIO, ord);
  }

  // Entregar el link
  setTimeout(function(){
    _biolargaBusy = false;
    if(btn){ btn.disabled = false; btn.textContent = 'Comprar ahora'; btn.style.opacity = '1'; }
    _refreshBioLargaSaldo();
    _mostrarBioLargaLink(ord);
  }, 600);
}

function _mostrarBioLargaLink(ord){
  var ov = document.getElementById('biolarga-modal');
  if(!ov){
    ov = document.createElement('div');
    ov.id = 'biolarga-modal';
    ov.className = 'modal-ov';
    document.body.appendChild(ov);
  }
  ov.innerHTML = '<div class="modal" style="max-width:420px">'
    + '<div style="padding:1.8rem 1.5rem;text-align:center">'
    +   '<div style="width:64px;height:64px;margin:0 auto 1rem;border-radius:18px;background:linear-gradient(160deg,#25d366,#3d4044);display:flex;align-items:center;justify-content:center;box-shadow:0 8px 24px rgba(37,211,102,.4)"><svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20 6 9 17l-5-5"/></svg></div>'
    +   '<div style="font-family:Barlow,sans-serif;font-weight:700;font-size:1.2rem;color:#fff;margin-bottom:.4rem">Compra exitosa!</div>'
    +   '<div style="font-size:.82rem;color:#9aa3b0;line-height:1.5;margin-bottom:1.3rem">Aqui esta tu enlace para BIO LARGA. Uselo hasta 5 veces al dia.</div>'
    +   '<div style="background:rgba(37,211,102,.08);border:1px solid rgba(37,211,102,.3);border-radius:12px;padding:1rem;margin-bottom:1rem">'
    +     '<a href="' + BIOLARGA_LINK + '" target="_blank" style="font-family:monospace;font-size:.95rem;color:#25d366;word-break:break-all;text-decoration:none;font-weight:700">' + BIOLARGA_LINK + '</a>'
    +   '</div>'
    +   '<div style="display:flex;gap:.6rem">'
    +     '<button onclick="_copiarBioLink()" style="flex:1;padding:.85rem;background:rgba(255,255,255,.05);border:1px solid rgba(255,255,255,.15);color:#fff;border-radius:11px;font-family:Barlow;font-weight:700;font-size:.85rem;cursor:pointer">Copiar</button>'
    +     '<button onclick="window.open(BIOLARGA_LINK,\'_blank\')" style="flex:1;padding:.85rem;background:linear-gradient(135deg,#128c3e,#25d366);color:#fff;border:none;border-radius:11px;font-family:Barlow;font-weight:700;font-size:.85rem;cursor:pointer">Abrir enlace</button>'
    +   '</div>'
    +   '<button onclick="document.getElementById(\'biolarga-modal\').classList.remove(\'show\')" style="width:100%;margin-top:.7rem;padding:.7rem;background:none;border:none;color:#6b7280;font-family:Barlow;font-size:.8rem;cursor:pointer">Cerrar</button>'
    +   '<div style="font-size:.68rem;color:#55595e;margin-top:.8rem">Pedido #' + ord + '</div>'
    + '</div></div>';
  ov.classList.add('show');
}

function _copiarBioLink(){
  var tmp = document.createElement('input');
  tmp.value = BIOLARGA_LINK;
  document.body.appendChild(tmp);
  tmp.select();
  try { document.execCommand('copy'); showToast('\u2705 Enlace copiado'); } catch(e){ showToast('Copia manual: ' + BIOLARGA_LINK); }
  document.body.removeChild(tmp);
}


