    var sr = r.filter(_s2SinResp).length, urg = ab.filter(function(t){ return t.priority === 'urgente'; }).length;
    _d2Set('d2-sop-n', _d2Num(sr)); _d2Set('d2-sop-sub', _d2Num(ab.length) + ' abiertos' + (urg ? ' · ' + urg + ' urgentes' : ''));
